"use client";

import Image from "next/image";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@radix-ui/react-dialog";
import { DialogHeader } from "@/components/ui/dialog";

// Type for user in assigned_users
type AssignedUser = {
  id: number;
  email: string;
  name: string;
};

// Type for role
type Role = {
  id: string;
  name: string;
  assigned_users: AssignedUser[];
};

type SuperAdmin = {
  name: string;
  email: string;
};

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { showErrorToast } from "@/utils/toasters";
import { LoaderCircleIcon } from "lucide-react";
import { fetchRoles, inviteSupes, transferSupes } from "@/services/admin";

const ManageSuperAdmin = () => {
  const [defaultTab, setDefaultTab] = useState("addNewUser");
  const route = useRouter();

  const [isLoadInvite, setIsLoadInvite] = useState(false);
  const [isLoadTransfer, setIsLoadTransfer] = useState(false);

  const [roles, setRoles] = useState<Role[]>([]);

  const [selectedUserIds, setSelectedUserIds] = useState<number[]>([]);
  const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);

  const [selectedInviteRoleId, setSelectedInviteRoleId] = useState<
    string | null
  >(null);

  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [showConfirmInviteModal, setShowConfirmInviteModal] = useState(false);

  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [showSuccessInviteModal, setShowSuccessInviteModal] = useState(false);

  const [actionTransferOption, setActionTransferOption] = useState("");
  const [changeRoleTransfer, setChangeRoleTransfer] = useState(false);

  const [actionInviteOption, setActionInviteOption] = useState("");
  const [changeRoleInvite, setChangeRoleInvite] = useState(false);

  const [newSuperAdmin, setNewSuperAdmin] = useState<SuperAdmin>({
    name: "",
    email: "",
  });

  const fetchRole = async () => {
    try {
      const response = await fetchRoles();
      setRoles(response.data.results || []);
    } catch (error) {
      // handle error
    }
  };

  useEffect(() => {
    fetchRole();
  }, []);

  const adminRoles = roles.filter((role) => role.name !== "Super Admin");

  const transferSuperAdminRole = async () => {
    try {
      const payload = {
        email:
          adminRoles
            .find((role) =>
              role.assigned_users.some((user) => user.id === selectedUserIds[0])
            )
            ?.assigned_users.find((user) => user.id === selectedUserIds[0])
            ?.email ?? "",
        transfer_action: actionTransferOption ?? "",
        new_role_id: selectedRoleId ?? "",
      };
      setIsLoadTransfer(true);
      await transferSupes(payload);
      await fetchRoles();
      setShowConfirmModal(false);
      setShowSuccessModal(true);
      setTimeout(() => route.push("/auth/login"), 3000);
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Cannot transfer role",
      });
    } finally {
      setIsLoadTransfer(false);
    }
  };

  const InviteSuperAdmin = async () => {
    try {
      const payload = {
        email: newSuperAdmin.email ?? "",
        name: newSuperAdmin.name ?? "",
        transfer_action: actionInviteOption ?? "",
        new_role_id: selectedInviteRoleId ?? "",
      };
      setIsLoadInvite(true);
      await inviteSupes(payload);
      await fetchRoles();
      setShowSuccessInviteModal(true);
      setTimeout(() => route.push("/auth/login"), 3000);
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Cannot Invite member",
      });
    } finally {
      setIsLoadInvite(false);
    }
  };

  return (
    <div className="flex min-h-screen bg-background rounded-lg">
      {/* Main Content */}
      <main className="w-full px-3">
        <div className="rounded-lg bg-card md:px-5 px-0 pt-5">
          <div className="flex items-center justify-normal lg:gap-72 gap-3 mb-5">
            <Image
              src="/assets/icons/arrow-back.svg"
              alt="arrow-back"
              width={20}
              height={20}
              className="font-bold cursor-pointer"
              onClick={() => route.back()}
            />
            <h1 className=" font-bold text-center ">Manage Super Admin role</h1>
          </div>
          <Tabs
            defaultValue="addNewUser"
            className="space-y-6"
            onValueChange={setDefaultTab}
          >
            <TabsList className="w-full border-b rounded-none bg-transparent p-0 h-auto">
              <TabsTrigger
                value="addNewUser"
                className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
              >
                Transfer to existing user
              </TabsTrigger>

              <TabsTrigger
                value="removeExistingUser"
                className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
              >
                Invite new user
              </TabsTrigger>
            </TabsList>

            <TabsContent value="addNewUser" className="space-y-4">
              <div>
                <p>Select user to transfer super admin privileges to</p>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <div>
                      <button className="w-full p-2 py-3 rounded-[8px] space-x-4 mt-3 border-[#9b9ea4] border-[1px] flex justify-between bg-transparent">
                        <span>
                          {selectedUserIds.length > 0
                            ? adminRoles
                                .find((role) =>
                                  role.assigned_users.some(
                                    (user) => user.id === selectedUserIds[0]
                                  )
                                )
                                ?.assigned_users.find(
                                  (user) => user.id === selectedUserIds[0]
                                )?.name
                            : "Select User"}
                        </span>

                        <img
                          src="/assets/icons/arrow-down.svg"
                          alt=""
                          className="w-3 h-3 ml-auto mt-2 mr-2"
                        />
                      </button>
                    </div>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent
                    align="start"
                    className="w-[var(--radix-popper-anchor-width)] min-w-[var(--radix-popper-anchor-width)]"
                  >
                    <div>
                      <DropdownMenuItem>
                        <div className="w-full">
                          {adminRoles.length === 0 ? (
                            <p className="text-center text-gray-500">
                              No users available to add.
                            </p>
                          ) : (
                            adminRoles.map((admin) =>
                              admin.assigned_users.map((user) => (
                                <div
                                  key={user.id}
                                  className="flex justify-between w-full items-center py-2"
                                  onClick={() => setSelectedUserIds([user.id])}
                                >
                                  <div className="flex justify-normal items-center gap-10 w-full">
                                    <p>{user.name || "Name"}</p>
                                    {/* <p className="text-muted-foreground">
                                          {user.email}
                                        </p> */}
                                  </div>

                                  <p className="text-blue-500 text-nowrap lg:text-base text-xs">
                                    {admin.name || "Role Name"}
                                  </p>
                                </div>
                              ))
                            )
                          )}
                        </div>
                        {/* )} */}
                      </DropdownMenuItem>
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
                <div className="pt-5">
                  <p>After transfer, select what happens to your account</p>
                  <div className="flex w-full justify-normal lg:flex-row flex-col lg:items-center gap-4 mt-3">
                    <div className="flex items-center gap-4">
                      <input
                        type="radio"
                        name="option"
                        value="change_role"
                        id="change-role"
                        onChange={(e) => {
                          setChangeRoleTransfer(true);
                          setActionTransferOption(e.target.value);
                        }}
                      />
                      <label htmlFor="change-role">Change my role</label>
                    </div>
                    <div className="flex items-center gap-4">
                      <input
                        type="radio"
                        name="option"
                        value="remove_access"
                        id="remove-access"
                        onChange={(e) => {
                          setChangeRoleTransfer(false);
                          setActionTransferOption(e.target.value);
                        }}
                      />
                      <label htmlFor="remove-access">
                        Remove my access completely
                      </label>
                    </div>
                  </div>
                  {changeRoleTransfer && (
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <div>
                          <button className="w-full p-2 py-3 rounded-[8px] space-x-4 mt-3 border-[#9b9ea4] border-[1px] flex justify-between bg-transparent">
                            <span>
                              {selectedRoleId
                                ? adminRoles.find(
                                    (role) => role.id === selectedRoleId
                                  )?.name
                                : "Select Role"}
                            </span>

                            <img
                              src="/assets/icons/arrow-down.svg"
                              alt=""
                              className="w-3 h-3 ml-auto mt-2 mr-2"
                            />
                          </button>
                        </div>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="start"
                        className="w-[var(--radix-popper-anchor-width)] min-w-[var(--radix-popper-anchor-width)]"
                      >
                        {adminRoles.length === 0 ? (
                          <p className="text-center text-gray-500">
                            No roles available.
                          </p>
                        ) : (
                          adminRoles.map((role, index) => (
                            <DropdownMenuItem
                              key={index}
                              className="w-full text-center px-4 py-2 hover:bg-gray-200"
                              onClick={() => setSelectedRoleId(role.id)}
                            >
                              {role.name}
                            </DropdownMenuItem>
                          ))
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  )}
                </div>
                <Button
                  disabled={
                    isLoadTransfer ||
                    selectedUserIds.length === 0 ||
                    !actionTransferOption ||
                    (changeRoleTransfer && !selectedRoleId)
                  }
                  onClick={() => setShowConfirmModal(true)}
                  className={`
               hover:bg-blue-800 cursor-pointer mt-24 w-full text-center`}
                >
                  Save Changes
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="removeExistingUser" className="space-y-8">
              <div>
                <p className="font-bold">Add New Super Admin Information</p>
                <div className="flex justify-between items-center py-3 w-full">
                  <div className="flex flex-col gap-2 w-full">
                    <p className="font-semibold">Name</p>
                    <input
                      type="text"
                      value={newSuperAdmin.name}
                      onChange={(e) =>
                        setNewSuperAdmin({
                          ...newSuperAdmin,
                          name: e.target.value,
                        })
                      }
                      name="name"
                      className="border border-black rounded-md p-2 w-full"
                    />
                  </div>
                </div>
                <div className="flex justify-between items-center py-3 w-full">
                  <div className="flex flex-col gap-2 w-full">
                    <p className="font-semibold">Email Address</p>
                    <input
                      type="email"
                      value={newSuperAdmin.email}
                      name="email"
                      onChange={(e) =>
                        setNewSuperAdmin({
                          ...newSuperAdmin,
                          email: e.target.value,
                        })
                      }
                      className="border border-black rounded-md p-2 w-full"
                    />
                  </div>
                </div>
                <div className="">
                  <p>After transfer, select what happens to your account</p>
                  <div className="flex w-full justify-normal lg:flex-row flex-col lg:items-center gap-4 mt-3">
                    <div className="flex items-center gap-4">
                      <input
                        type="radio"
                        name="transfer"
                        id=""
                        value="change_role"
                        onChange={(e) => {
                          setChangeRoleInvite(true);
                          setActionInviteOption(e.target.value);
                        }}
                      />
                      <label htmlFor="change-role">Change my role</label>
                    </div>
                    <div className="flex items-center gap-4">
                      <input
                        type="radio"
                        name="transfer"
                        id=""
                        value="remove_access"
                        onChange={(e) => {
                          setChangeRoleInvite(false);
                          setActionInviteOption(e.target.value);
                        }}
                      />
                      <label htmlFor="remove-access">
                        Remove my access completely
                      </label>
                    </div>
                  </div>

                  {changeRoleInvite && (
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <button className="w-full p-2 py-3 rounded-[8px] space-x-4 mt-3 border-[#9b9ea4] border-[1px] flex justify-between bg-transparent">
                          <span>
                            {selectedInviteRoleId
                              ? adminRoles.find(
                                  (role) => role.id === selectedInviteRoleId
                                )?.name
                              : "Select Role"}
                          </span>

                          <img
                            src="/assets/icons/arrow-down.svg"
                            alt=""
                            className="w-4 h-4 ml-auto"
                          />
                        </button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="start"
                        className="w-[var(--radix-popper-anchor-width)] min-w-[var(--radix-popper-anchor-width)]"
                      >
                        {adminRoles.map((role, index) => (
                          <DropdownMenuItem
                            key={index}
                            className="w-full text-center px-4 py-2 hover:bg-gray-200"
                            onClick={() => setSelectedInviteRoleId(role.id)}
                          >
                            {role.name}
                          </DropdownMenuItem>
                        ))}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  )}
                </div>
                <Button
                  disabled={
                    isLoadInvite ||
                    selectedInviteRoleId?.length === 0 ||
                    !actionInviteOption ||
                    (changeRoleInvite && !selectedInviteRoleId)
                  }
                  onClick={() => setShowConfirmInviteModal(true)}
                  className="
                bg-[#023E8A] hover:bg-blue-800 cursor-pointer mt-24 w-full text-center"
                >
                  Send invitation
                </Button>
              </div>
            </TabsContent>
          </Tabs>
        </div>

        {/* Confirm Member Transfer Modal */}
        <Dialog open={showConfirmModal} onOpenChange={setShowConfirmModal}>
          <DialogContent className="w-full lg:max-w-lg max-w-sm p-4 rounded-lg bg-white shadow-2xl absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
            <div className="lg:space-y-[40px] space-y-3 flex flex-col items-center">
              <DialogHeader className="text-left">
                <DialogTitle className="text-xl font-bold text-[#181818]">
                  Confirm Member Transfer?
                </DialogTitle>
              </DialogHeader>
              <DialogDescription className="lg:text-base text-[12px] text-gray-700 text-left px-4 font-[500]">
                You are about to add this selected user to this role. These
                users will be removed from their current roles. Do you want to
                proceed?
              </DialogDescription>
            </div>
            <div className="flex items-center gap-2 justify-end lg:pt-5 pt-2">
              <Button
                className="border text-black border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
                onClick={() => setShowConfirmModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => {
                  transferSuperAdminRole();
                }}
                className="bg-[#023E8A] p-2 px-4 hover:bg-blue-700 cursor-pointer"
              >
                {isLoadTransfer && (
                  <LoaderCircleIcon
                    stroke="#ffffff"
                    style={{ animation: "spin 1s linear infinite" }}
                  />
                )}
                Yes, Proceed
              </Button>
            </div>
          </DialogContent>
        </Dialog>
        {/* Success Modal for Adding New User */}
        <Dialog open={showSuccessModal} onOpenChange={setShowSuccessModal}>
          <DialogContent className="w-full lg:max-w-sm max-w-sm p-8">
            <div className="flex flex-col items-center">
              <DialogHeader className="text-center">
                <DialogTitle className="text-xl font-[500] text-[#181818]">
                  Success
                </DialogTitle>
              </DialogHeader>
              <img
                src="/assets/icons/blue-success.svg"
                alt="Success"
                className="w-20 h-20 my-6"
              />
              <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-bold">
                User Added Successfully
              </DialogDescription>
            </div>
          </DialogContent>
        </Dialog>

        {/* Confirm Super Admin Invite Modal */}
        <Dialog
          open={showConfirmInviteModal}
          onOpenChange={setShowConfirmInviteModal}
        >
          <DialogContent className="w-full lg:max-w-xl max-w-sm p-8 rounded-lg bg-white shadow-2xl absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
            <div className="space-y-[40px] flex flex-col items-center">
              <DialogHeader className="text-justify">
                <DialogTitle className="text-xl font-bold text-[#181818]  text-justify">
                  Confirm Super Admin Invite?
                </DialogTitle>
              </DialogHeader>
              <DialogDescription className="lg:text-base text-[12px] text-gray-700 text-left px-4 font-[500]">
                You are about to invite and transfer Super Admin privileges to
                <strong> {newSuperAdmin.email}</strong> and{" "}
                {actionInviteOption === "remove_access"
                  ? `completely remove your access to the
                TravelMate dashboard`
                  : `your account will be changed to ${
                      adminRoles.find(
                        (role) => role.id === selectedInviteRoleId
                      )?.name
                    } role`}
                . This action cannot be undone. Are you sure you want to
                proceed?
              </DialogDescription>
            </div>
            <div className="flex items-center gap-2 justify-end pt-5">
              <Button
                className="border text-[#023E8A] border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
                onClick={() => setShowConfirmInviteModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => {
                  InviteSuperAdmin();
                }}
                className="bg-[#D72638] p-2 px-4 hover:bg-red-700 cursor-pointer"
              >
                {isLoadInvite && (
                  <LoaderCircleIcon
                    stroke="#ffffff"
                    style={{ animation: "spin 1s linear infinite" }}
                  />
                )}
                Yes, Proceed
              </Button>
            </div>
          </DialogContent>
        </Dialog>

        {/* Success Modal for Inviting Users */}
        <Dialog
          open={showSuccessInviteModal}
          onOpenChange={setShowSuccessInviteModal}
        >
          <DialogContent className="w-full lg:max-w-sm max-w-sm p-8">
            <div className="flex flex-col items-center">
              <DialogHeader className="text-center">
                <DialogTitle className="text-xl font-[500] text-[#181818]">
                  Super Admin Invitation Sent Successfully!
                </DialogTitle>
              </DialogHeader>
              <img
                src="/assets/icons/blue-success.svg"
                alt="Success"
                className="w-20 h-20 my-6"
              />
              <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-bold">
                An invitation email has been sent to {newSuperAdmin.email} and
                Your role has been changed to an{" "}
                {adminRoles.find((role) => role.id === selectedInviteRoleId)
                  ?.name || "Admin"}
                .
              </DialogDescription>
            </div>
          </DialogContent>
        </Dialog>
      </main>
    </div>
  );
};

export default ManageSuperAdmin;

"use client";

import Image from "next/image";
import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { LoaderCircleIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogHeader,
  DialogDescription,
} from "@/components/ui/dialog";
import env from "@/config/env";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { DeleteIcon, RemoveFormattingIcon, SearchIcon, X } from "lucide-react";
import Loading from "../../loading";
import { showErrorToast } from "@/utils/toasters";
import { assignUserToRole, fetchRoles, removeUsersFromRole } from "@/services/admin";

type AssignedUser = {
  id: number;
  email: string;
  name: string;
};
type Roles = {
  id: string;
  name: string;
  assigned_users: AssignedUser[];
};

const ManageUsers = () => {
  const [defaultTab, setDefaultTab] = useState("addNewUser");
  const route = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [addUSerModal, setIsAddUserModal] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  // New state for "Remove Existing Users" modals
  const [showConfirmRemoveModal, setShowConfirmRemoveModal] = useState(false);
  const [showSuccessRemoveModal, setShowSuccessRemoveModal] = useState(false);

  const params = useParams();
  const roleId = params?.id as string;

  const [loading, setLoading] = useState(true);
  const [roles, setRoles] = useState<Roles[]>([]);
  const [selectedUserIds, setSelectedUserIds] = useState<number[]>([]);

  const [selectedUserIdRemove, setSelectedUserIdRemove] = useState<number[]>(
    []
  );
  const [isLoadRemove, setIsLoadRemove] = useState(false);
  const [isLoadAdd, setIsLoadAdd] = useState(false);

  const currentRole = roles.find((role) => String(role.id) === String(roleId));

  const handleSelectAdd = (userId: number) => {
    setSelectedUserIds((prevSelected) =>
      prevSelected.includes(userId)
        ? prevSelected.filter((id) => id !== userId)
        : [...prevSelected, userId]
    );
  };
  const handleSelectRemove = (userId: number) => {
    setSelectedUserIdRemove((prevSelected) =>
      prevSelected.includes(userId)
        ? prevSelected.filter((id) => id !== userId)
        : [...prevSelected, userId]
    );
  };

  const fetchRole = async () => {
    try {
      setLoading(true);
      const response = await fetchRoles();
      setRoles(response.data.results || []);
    } catch (error) {
      console.error("Error fetching roles:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRole();
  }, []);

  const usersAssignedToOtherRoles = roles
    .filter(
      (role) =>
        String(role.id) !== String(roleId) && role.name !== "Super Admin"
    )
    .flatMap((role) =>
      role.assigned_users.map((user) => ({
        ...user,
        roleName: role.name,
      }))
    );

  const addUsersToRole = async () => {
    const emailsToAdd = usersAssignedToOtherRoles
      .filter((user) => selectedUserIds.includes(user.id))
      .map((user) => user.email.trim());
    try {
      setIsLoadAdd(true);
      await assignUserToRole(roleId, emailsToAdd.join(","));
      setShowConfirmModal(false);
      setShowSuccessModal(true);
      setSelectedUserIds([]);
      await fetchRoles();
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Failed to add users.",
      });
    } finally {
      setIsLoadAdd(false);
    }
  };

  const removeExistingUsers = async () => {
    const emailsToRemove = roles
      .filter((role) => String(role.id) === String(roleId))
      .flatMap((role) =>
        role.assigned_users
          .filter((user) => selectedUserIdRemove.includes(user.id))
          .map((user) => user.email.trim())
      );
    try {
      setIsLoadRemove(true);
      await removeUsersFromRole(roleId, emailsToRemove)
      setShowConfirmRemoveModal(false);
      setShowSuccessRemoveModal(true);
      setSelectedUserIdRemove([]);
      await fetchRoles();
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Failed to remove users.",
      });
    } finally {
      setIsLoadRemove(false);
    }
  };
  useEffect(() => {
    if (showSuccessModal || showSuccessRemoveModal) {
      const timeout = setTimeout(() => {
        setShowSuccessModal(false);
        setShowSuccessRemoveModal(false);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  });

  //SEARCH USERS TO ADD
  const handleSearch = (e: any) => {
    setSearchQuery(e.target.value);
  };
  return (
    <div className="flex min-h-screen bg-background rounded-lg">
      <main className="w-full">
        <div className="rounded-lg bg-card md:px-5 px-0 pt-5">
          <div className="flex items-center justify-normal lg:gap-72 gap-32 mb-5">
            <Image
              src="/assets/icons/arrow-back.svg"
              alt="arrow-back"
              width={20}
              height={20}
              className="font-bold cursor-pointer"
              onClick={() => route.back()}
            />
            <h1 className="text-lg font-bold text-center ">Manage User</h1>
          </div>
          <Tabs
            defaultValue="addNewUser"
            className="space-y-6"
            onValueChange={setDefaultTab}
          >
            <TabsList className="w-full border-b rounded-none bg-transparent p-0 h-auto">
              <TabsTrigger
                value="addNewUser"
                className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
              >
                Add New User
              </TabsTrigger>

              <TabsTrigger
                value="removeExistingUser"
                className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
              >
                Remove Existing User
              </TabsTrigger>
            </TabsList>

            <TabsContent value="addNewUser" className="space-y-4 px-3">
              <div>
                <p>Assign user from another role</p>
                <div onClick={() => setIsAddUserModal(true)}>
                  <button className="w-full p-2 py-3 rounded-[8px] space-x-4 mt-3 border-[#9b9ea4] border-[1px] flex justify-between bg-transparent">
                    <span>
                      {selectedUserIds.length > 0
                        ? `${selectedUserIds.length} user${
                            selectedUserIds.length > 1 ? "s" : ""
                          } selected`
                        : "Select User"}
                    </span>

                    <img
                      src="/assets/icons/arrow-down.svg"
                      alt=""
                      className="w-3 h-3 ml-auto mt-2 mr-2"
                    />
                  </button>
                </div>
                <Dialog open={addUSerModal} onOpenChange={setIsAddUserModal}>
                  <DialogContent className="fixed md:top-[10vh] top-[20vh] left-1/2 max-w-2xl mt-64 mb-64 overflow-y-auto w-[90vw] max-h-[85vh]">
                    <DialogHeader>
                      <DialogTitle></DialogTitle>
                    </DialogHeader>
                    <div className="space-y-6">
                      <div className="space-y-4 py-10">
                        <div className="flex justify-normal items-center relative">
                          <SearchIcon className="w-5 absolute left-3" />
                          <input
                            type="search"
                            className="w-full border border-black rounded-lg p-2 pl-10"
                            placeholder="Search Users"
                            value={searchQuery}
                            onChange={handleSearch}
                          />
                        </div>

                        {loading ? (
                          <Loading />
                        ) : (
                          <div className="space-y-4">
                            {usersAssignedToOtherRoles.length === 0 ? (
                              <p className="text-center text-gray-500">
                                No users available to add.
                              </p>
                            ) : (
                              usersAssignedToOtherRoles
                                .filter(
                                  (user) =>
                                    user.email
                                      .toLowerCase()
                                      .includes(searchQuery.toLowerCase()) ||
                                    user.email
                                      .toLowerCase()
                                      .includes(searchQuery.toLowerCase())
                                )
                                .map((user, index) => (
                                  <div
                                    key={index}
                                    className="flex justify-between w-full lg:items-center items-start py-2 border-b"
                                  >
                                    <div className="flex justify-normal items-center gap-10">
                                      <input
                                        type="checkbox"
                                        name={`add-${user.id}`}
                                        id={`add-${user.id}`}
                                        checked={selectedUserIds.includes(
                                          user.id
                                        )}
                                        onChange={() =>
                                          handleSelectAdd(user.id)
                                        }
                                      />

                                      <div>
                                        <p>{user.name || "Unkownn user"}</p>
                                        <p className="text-muted-foreground">
                                          {user.email}
                                        </p>
                                      </div>
                                    </div>

                                    <p className="text-blue-500 text-nowrap lg:text-base text-xs">
                                      {user.roleName}
                                    </p>
                                  </div>
                                ))
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>

                <div className="flex justify-normal gap-5 items-start">
                  {selectedUserIds.length
                    ? usersAssignedToOtherRoles
                        .filter((user) => selectedUserIds.includes(user.id))
                        .map((user, index) => (
                          <div
                            key={index}
                            className="flex justify-normal items-center align-middle gap-4 bg-[#F5F5F5] p-2 mt-4 w-fit"
                          >
                            <p>{user.name}</p>
                            <X
                              fontSize={2}
                              className="w-4 h-4 mt-[2px] cursor-pointer"
                              onClick={() =>
                                setSelectedUserIds((prev) =>
                                  prev.filter((id) => id !== user.id)
                                )
                              }
                            />
                          </div>
                        ))
                    : null}
                </div>

                <Button
                  onClick={() => setShowConfirmModal(true)}
                  className="bg-[#023E8A] hover:bg-blue-800 cursor-pointer mt-24 w-full text-center"
                >
                  Add
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="removeExistingUser" className="space-y-8 px-3">
              <div>
                <p className="font-bold">Select Users to remove</p>
                {roles
                  .filter((role) => String(role.id) === String(roleId))
                  .flatMap((role) => role.assigned_users)
                  .map((user) => (
                    <div
                      key={user.id}
                      className="flex justify-between items-center py-3 w-full"
                    >
                      <div>
                        <p>{user.name}</p>
                        <p>{user.email}</p>
                      </div>
                      <input
                        type="checkbox"
                        name={`remove-${user.id}`}
                        id={`remove-${user.id}`}
                        checked={selectedUserIdRemove?.includes(user.id)}
                        onChange={() => handleSelectRemove(user.id)}
                      />
                    </div>
                  ))}
                <Button
                  onClick={() => setShowConfirmRemoveModal(true)}
                  className="bg-[#D72638] hover:bg-red-800 cursor-pointer mt-24 w-full text-center"
                  disabled={selectedUserIdRemove.length < 1}
                >
                  Remove
                </Button>
              </div>
            </TabsContent>
          </Tabs>
        </div>

        {/* Confirm Member Transfer Modal */}
        <Dialog open={showConfirmModal} onOpenChange={setShowConfirmModal}>
          <DialogContent className="w-full lg:max-w-lg max-w-sm p-4">
            <div className="lg:space-y-[40px] space-y-3 flex flex-col items-center">
              <DialogHeader className="text-left">
                <DialogTitle className="text-xl font-bold text-[#181818]">
                  Confirm Member Transfer?
                </DialogTitle>
              </DialogHeader>
              <DialogDescription className="lg:text-base text-[12px] text-gray-700 text-left px-4 font-[500]">
                You are about to add {selectedUserIds.length} selected user
                {selectedUserIds.length > 1 && `s`} to this role. These users
                will be removed from their current roles. Do you want to
                proceed?
              </DialogDescription>
            </div>
            <div className="flex items-center gap-2 justify-end lg:pt-5 pt-2">
              <Button
                className="border text-black border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
                onClick={() => setShowConfirmModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => {
                  addUsersToRole();
                }}
                className="bg-[#023E8A] p-2 px-4 hover:bg-blue-700 cursor-pointer"
              >
                {isLoadAdd && (
                  <LoaderCircleIcon
                    stroke="#ffffff"
                    style={{ animation: "spin 1s linear infinite" }}
                  />
                )}
                Yes, Proceed
              </Button>
            </div>
          </DialogContent>
        </Dialog>

        {/* Success Modal for Adding New User */}
        <Dialog open={showSuccessModal} onOpenChange={setShowSuccessModal}>
          <DialogContent className="w-full lg:max-w-sm max-w-sm p-8">
            <div className="flex flex-col items-center">
              <DialogHeader className="text-center">
                <DialogTitle className="text-xl font-[500] text-[#181818]">
                  Success
                </DialogTitle>
              </DialogHeader>
              <img
                src="/assets/icons/blue-success.svg"
                alt="Success"
                className="w-20 h-20 my-6"
              />
              <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-bold">
                User Added Successfully
              </DialogDescription>
            </div>
          </DialogContent>
        </Dialog>

        {/* Confirm Remove Users Modal */}
        <Dialog
          open={showConfirmRemoveModal}
          onOpenChange={setShowConfirmRemoveModal}
        >
          <DialogContent className="w-full lg:max-w-lg max-w-sm p-4">
            <div className="space-y-[40px] flex flex-col items-center">
              <DialogHeader className="text-left">
                <DialogTitle className="text-xl font-bold text-[#181818]">
                  Confirm Remove Users?
                </DialogTitle>
              </DialogHeader>
              <DialogDescription className="lg:text-base text-[12px] text-gray-700 text-left px-4 font-[500]">
                You are about to remove the selected users from{" "}
                {currentRole?.name} role. They will no longer have access to
                these role permissions. Do you want to proceed?
              </DialogDescription>
            </div>
            <div className="flex items-center gap-2 justify-end pt-5">
              <Button
                className="border text-black border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
                onClick={() => setShowConfirmRemoveModal(false)}
              >
                Cancel
              </Button>
              <Button
                onClick={() => {
                  removeExistingUsers();
                }}
                className="bg-[#023E8A] p-2 px-4 hover:bg-blue-700 cursor-pointer"
              >
                {isLoadRemove && (
                  <LoaderCircleIcon
                    stroke="#ffffff"
                    style={{ animation: "spin 1s linear infinite" }}
                  />
                )}
                Yes, Proceed
              </Button>
            </div>
          </DialogContent>
        </Dialog>

        {/* Success Modal for Removing Users */}
        <Dialog
          open={showSuccessRemoveModal}
          onOpenChange={setShowSuccessRemoveModal}
        >
          <DialogContent className="w-full lg:max-w-sm max-w-sm p-8">
            <div className="flex flex-col items-center">
              <DialogHeader className="text-center">
                <DialogTitle className="text-xl font-[500] text-[#181818]"></DialogTitle>
              </DialogHeader>
              <img
                src="/assets/icons/blue-success.svg"
                alt="Success"
                className="w-20 h-20 my-6"
              />
              <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-bold">
                Users Removed Successfully
              </DialogDescription>
            </div>
          </DialogContent>
        </Dialog>
      </main>
    </div>
  );
};

export default ManageUsers;

"use client";

import React, { useEffect, useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Checkbox } from "@/components/ui/checkbox";
import RoleManagement from "../../../components/molecues/admin/RoleManagement";
import RoleAssignment from "../../../components/molecues/admin/RoleAssignment";
import { showErrorToast, showSuccessToast } from "@/utils/toasters";
import Loading from "./loading";
import { LoaderCircleIcon } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuItem,
  DropdownMenuContent,
} from "@/components/ui/dropdown-menu";
import { Download, XCircle } from "lucide-react";
import {
  addRRoles,
  deleteRoles,
  fetchPermission,
  fetchRoles,
  inviteMembers,
  revokeInvites,
  updateRoles,
} from "@/services/admin";

interface User {
  name: string;
  email: string;
}

interface Role {
  id: string;
  name: string;
  description: string;
  assigned_users: User[];
  current_permission_group_slugs: string[];
  is_superuser: boolean;
  created_by: string;
  invited_users: User[];
}

type Permissions = {
  slug: string;
  name: string;
};

const AdminRolesPage: React.FC = () => {
  const router = useRouter();

  const [isLoading, setIsLoading] = useState(true);
  const [isPermissionLoading, setIsPermissionLoading] = useState(true);
  const [isDeleteLoading, setIsDeleteLoading] = useState(false);
  const [isSaveLoading, setIsSaveLoading] = useState(false);
  const [isInviteLoading, setIsInviteLoading] = useState(false);

  const [isEditing, setIsEditing] = useState(false);
  const [editingRoleId, setEditingRoleId] = useState<string | null>(null);

  const [isCreateRoleOpen, setIsCreateRoleOpen] = useState(false);
  const [isAddMemberOpen, setIsAddMemberOpen] = useState(false);

  const [roleToDelete, setRoleToDelete] = useState<string | null>(null);
  const [successModal, setSuccessModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [successDeleteModal, setSuccessDeleteModal] = useState(false);

  const [activeTab, setActiveTab] = useState("role-management");

  const [adminDetails, setAdminDetails] = useState<Role[]>([]);
  const [availablePermissions, setAvailablePermissions] = useState<
    Permissions[]
  >([]);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isInvited, setIsInvited] = useState(false);

  const [roleDetails, setRoleDetails] = useState<{
    id: string;
    name: string;
    description: string;
    permissions: string[];
  }>({
    id: "",
    name: "",
    description: "",
    permissions: [],
  });

  const [newMember, setNewMember] = useState<{
    id: string;
    name: string;
    email: string;
    role: string;
  }>({
    id: "",
    name: "",
    email: "",
    role: "",
  });

  const admins = adminDetails.filter((admin) => admin.name !== "Super Admin");

  // FETCH PERMISSIONS TO CREATE NEW ROLE
  const fetchPermissions = async () => {
    try {
      setIsPermissionLoading(true);
      const response = await fetchPermission();
      setAvailablePermissions(
        Array.isArray(response.data.results) ? response.data.results : []
      );
    } catch (error: any) {
      console.error(
        "Error fetching permissions:",
        error.response?.data || error.message
      );
      setAvailablePermissions([]);
      showErrorToast({
        message:
          error.response?.data?.detail?.[0] ||
          error.response?.data?.messages?.[0] ||
          error.message,
      });
    } finally {
      setIsPermissionLoading(false);
    }
  };

  // FETCH ALL ROLES
  const fetchAllRoles = async () => {
    try {
      setIsLoading(true);
      const response = await fetchRoles();
      setAdminDetails(
        Array.isArray(response.data.results) ? response.data.results : []
      );
    } catch (error: any) {
      showErrorToast({
        message: error.response?.data?.detail?.[0] || error?.messages?.message,
      });
    } finally {
      setIsLoading(false);
    }
  };

  // UPDATE ADMIN ROLES AND PERMISSIONS
  const UpdateRole = async (roleId: string, updatedRole: Partial<Role>) => {
    try {
      setIsSaveLoading(true);
      const payload = {
        name: updatedRole.name ?? "",
        description: updatedRole.description ?? "",
        permission_group_slugs:
          updatedRole.current_permission_group_slugs ?? [],
      };
      const response = await updateRoles(roleId, payload);
      setAdminDetails((prev) =>
        prev.map((role) =>
          role.id === roleId
            ? {
                ...role,
                name: response.data.name,
                description: response.data.description,
                current_permission_group_slugs:
                  response.data.current_permission_group_slugs || [],
                assigned_users: response.data.assigned_users || [],
                invited_users: response.data.invited_users || [],
              }
            : role
        )
      );
      setRoleDetails((prev) => ({
        ...prev,
        permissions: response.data.current_permission_group_slugs || [],
      }));
      showSuccessToast({
        message: "Role updated successfully",
      });
    } catch (error: any) {
      console.error(
        "Error updating role:",
        error.response?.data || error.message
      );
      showErrorToast({
        message: error?.response?.data?.message || "Failed to update role",
      });
    } finally {
      setIsSaveLoading(false);
    }
  };

  // CREATE NEW ROLE OR SAVE
  const saveRole = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (
      !roleDetails.name ||
      roleDetails.name.trim() === "" ||
      !roleDetails.description ||
      !roleDetails.permissions.length
    ) {
      showErrorToast({
        message: "Fill in complete details and assign permissions to role",
      });
      return;
    }
    if (isEditing && editingRoleId) {
      await UpdateRole(editingRoleId, {
        name: roleDetails.name,
        description: roleDetails.description,
        current_permission_group_slugs: roleDetails.permissions,
      });
      setIsCreateRoleOpen(false);
      setIsEditing(false);
      setEditingRoleId(null);
    } else {
      try {
        const payload = {
          name: roleDetails.name,
          description: roleDetails.description,
          permission_group_slugs: roleDetails.permissions,
        };
        setIsSaveLoading(true);
        const response = await addRRoles(payload);
        setAdminDetails((prev) => [...prev, response.data]);
        showSuccessToast({
          message: "Created new role successfully!",
        });
        setIsCreateRoleOpen(false);
      } catch (err: any) {
        console.log("Error Creating new Role", err);
        showErrorToast({
          message: err?.response?.data?.message || "An error occurred",
        });
      } finally {
        setIsSaveLoading(false);
        setRoleDetails({ id: "", name: "", description: "", permissions: [] });
      }
    }
  };

  useEffect(() => {
    fetchPermissions();
    fetchAllRoles();
  }, []);

  // Handle role details input changes
  const handleChangeRoleDetails = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setRoleDetails((prev) => ({ ...prev, [name]: value }));
  };

  const handleNewInvite = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewMember((prev) => ({ ...prev, [name]: value }));
  };

  // Handle permission checkbox changes
  const handlePermissionChange = (id: string, checked: boolean) => {
    setRoleDetails((prev) => ({
      ...prev,
      permissions: checked
        ? [...prev.permissions, id]
        : prev.permissions.filter((permId) => permId !== id),
    }));
  };

  // EDIT ADMIN ROLES
  const handleEditRole = (role: Role) => {
    setRoleDetails({
      id: role.id,
      name: role.name,
      description: role.description,
      permissions: role.current_permission_group_slugs || [],
    });
    setEditingRoleId(role.id);
    setIsEditing(true);
    setIsCreateRoleOpen(true);
  };

  // DELETE ROLES
  const confirmDeleteRole = async () => {
    try {
      setIsDeleteLoading(true);
      await deleteRoles(roleToDelete);
      setAdminDetails((prev) =>
        prev.filter((role) => role.id !== roleToDelete)
      );
      setShowConfirmModal(false);
      setSuccessDeleteModal(true);
      showSuccessToast({ message: "Role deleted successfully!" });
    } catch (error: any) {
      showErrorToast({
        message:
          error?.response?.data?.message || "Error deleting Role, try again",
      });
    } finally {
      setIsDeleteLoading(false);
    }
  };

  // INVITE NEW MEMBER
  const inviteMember = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const role = adminDetails.find((role) => role.name === selectedOption);
    const id = role?.id || "";
    if (!newMember.name || !newMember.email || !newMember.role) {
      showErrorToast({ message: "Fill in all the details" });
      return;
    }
    try {
      const payload = {
        email: newMember.email,
        name: newMember.name,
      };

      setIsInviteLoading(true);
      await inviteMembers(id, payload);
      setIsAddMemberOpen(false);
      setSuccessModal(true);
      setAdminDetails((prev) =>
        prev.map((role) =>
          role.id === id
            ? {
                ...role,
                invited_users: [
                  ...role.invited_users,
                  { name: newMember.name, email: newMember.email },
                ],
              }
            : role
        )
      );
      setIsInvited(true);
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Cannot add new member",
      });
    } finally {
      setSelectedOption("");
      setIsInviteLoading(false);
    }
  };

  // REVOKE INVITATION OF ADMINS AND SUPERADMINS
  const revokeInvite = async (id: string, email: string) => {
    try {
      await revokeInvites(id, email);
      setAdminDetails((prev) =>
        prev.map((role) =>
          role.id === id
            ? {
                ...role,
                invited_users: role.invited_users.filter(
                  (user) => user.email !== email
                ),
              }
            : role
        )
      );
    } catch (error: any) {
      console.log("error revoking invite", error);
      showErrorToast({
        message:
          error?.response?.data?.message ||
          "Error revoking invite member, please try again ",
      });
    }
  };

  const AdminRolesSkeletonLoader = () => {
    return (
      <div className="flex min-h-screen bg-background rounded-lg">
        <main className="w-full">
          <div className="rounded-lg bg-card md:px-5 px-0 pt-5">
            <div className="h-6 bg-gray-300 rounded-md w-3/4 mb-6 animate-pulse"></div>
            <div className="flex border-b mb-6">
              {[1, 2].map((_, index) => (
                <div
                  key={index}
                  className="h-10 w-32 bg-gray-300 rounded-md mr-4 animate-pulse"
                ></div>
              ))}
            </div>
            <div className="space-y-6">
              <div className="space-y-4">
                {[1, 2, 3].map((_, index) => (
                  <div
                    key={index}
                    className="h-16 bg-gray-300 rounded-md animate-pulse"
                  ></div>
                ))}
              </div>
              <div className="space-y-4">
                {[1, 2, 3].map((_, index) => (
                  <div
                    key={index}
                    className="h-16 bg-gray-300 rounded-md animate-pulse"
                  ></div>
                ))}
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="flex min-h-screen bg-background rounded-lg">
      <main className="w-full">
        {isLoading ? (
          <AdminRolesSkeletonLoader />
        ) : (
          <>
            <div className="rounded-lg bg-card md:px-5 px-0 pt-5">
              <h2 className="text-lg font-medium pb-6 px-2">
                Manage access control for your travel agency dashboard
              </h2>
              <Tabs
                defaultValue="role-management"
                className="space-y-6"
                onValueChange={setActiveTab}
              >
                <TabsList className="w-full border-b rounded-none bg-transparent p-0 h-auto">
                  <TabsTrigger
                    value="role-management"
                    className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
                  >
                    Role Management
                  </TabsTrigger>
                  <TabsTrigger
                    value="role-assignments"
                    className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-2 cursor-pointer"
                  >
                    Role Assignments
                  </TabsTrigger>
                </TabsList>
                <TabsContent value="role-management" className="space-y-4">
                  <RoleManagement
                    roles={adminDetails}
                    onCreateRoleOpen={() => setIsCreateRoleOpen(true)}
                    isLoading={isLoading}
                    onStartEdit={handleEditRole}
                    roleToDelete={roleToDelete}
                    setRoleToDelete={setRoleToDelete}
                    showConfirmModal={showConfirmModal}
                    setShowConfirmModal={setShowConfirmModal}
                    successDeleteModal={successDeleteModal}
                    setSuccessDeleteModal={setSuccessDeleteModal}
                    confirmDeleteRole={confirmDeleteRole}
                    isDeleteLoading={isDeleteLoading}
                  />
                </TabsContent>
                <TabsContent value="role-assignments" className="space-y-8">
                  <RoleAssignment
                    onCreateRoleOpen={() => setIsCreateRoleOpen(true)}
                    roles={adminDetails}
                    isLoading={isLoading}
                    onAddMemberOpen={() => setIsAddMemberOpen(true)}
                    revokeInvite={revokeInvite}
                    setAdminDetails={setAdminDetails}
                  />
                </TabsContent>
              </Tabs>
            </div>
            <Dialog
              open={isCreateRoleOpen}
              onOpenChange={(open) => {
                setIsCreateRoleOpen(open);
                if (!open) {
                  setIsEditing(false);
                  setRoleDetails({
                    id: "",
                    name: "",
                    description: "",
                    permissions: [],
                  });
                }
              }}
            >
              <DialogContent className="fixed md:top-[10vh] top-[20vh] left-1/2 max-w-2xl mt-64 mb-64 overflow-y-auto w-[90vw] max-h-[80vh]">
                <DialogHeader>
                  <DialogTitle>
                    {isEditing ? "Edit Role" : "Create New Role"}
                  </DialogTitle>
                </DialogHeader>
                <form onSubmit={saveRole}>
                  <div className="space-y-4">
                    <div className="pt-4">
                      <label className="text-sm font-medium">Role Name</label>
                      <Input
                        className="mt-2"
                        name="name"
                        value={roleDetails.name}
                        onChange={handleChangeRoleDetails}
                      />
                    </div>
                    <div className="pt-4">
                      <label className="text-sm font-medium">Description</label>
                      <Input
                        className="mt-2"
                        name="description"
                        value={roleDetails.description}
                        onChange={handleChangeRoleDetails}
                      />
                    </div>
                  </div>
                  <div className="space-y-6 pt-4">
                    <h3 className="text-sm font-medium">Permissions</h3>
                    {isPermissionLoading && <Loading />}
                    {availablePermissions.map((perm, id) => (
                      <div
                        key={perm.slug}
                        className="flex items-center space-x-2"
                      >
                        <Checkbox
                          className="cursor-pointer"
                          id={String(id)}
                          checked={roleDetails.permissions.includes(perm.slug)}
                          onCheckedChange={(checked: boolean) =>
                            handlePermissionChange(perm.slug, checked)
                          }
                        />
                        <label htmlFor={String(id)} className="capitalize">
                          {perm.name}
                        </label>
                      </div>
                    ))}
                  </div>
                  <div className="flex justify-between items-center w-full gap-4 mt-7">
                    <Button
                      variant="outline"
                      onClick={() => setIsCreateRoleOpen(false)}
                      className="bg-[#FFE2D2] hover:bg-orange-100 text-[#FF6F1E] cursor-pointer flex gap-3 items-center w-full"
                    >
                      <XCircle className="w-5" /> <span>CANCEL</span>
                    </Button>
                    <Button
                      disabled={isSaveLoading}
                      type="submit"
                      className="bg-[#CCD8E8] hover:bg-blue-100 text-[#023E8A] cursor-pointer flex gap-3 items-center w-full"
                    >
                      {isSaveLoading ? (
                        <LoaderCircleIcon
                          stroke="#023E8A"
                          style={{ animation: "spin 1s linear infinite" }}
                        />
                      ) : (
                        <Download className="w-5" />
                      )}
                      <span className="text-[#023E8A]">
                        {isEditing ? "UPDATE ROLE" : "SAVE ROLE"}
                      </span>
                    </Button>
                  </div>
                </form>
              </DialogContent>
            </Dialog>
            <Dialog open={isAddMemberOpen} onOpenChange={setIsAddMemberOpen}>
              <DialogContent>
                <DialogHeader className="border-b pb-2">
                  <DialogTitle className="text-center">
                    Invite New Member
                  </DialogTitle>
                </DialogHeader>
                <form className="flex flex-col gap-4" onSubmit={inviteMember}>
                  <div className="flex flex-col gap-3">
                    <label htmlFor="name">Name</label>
                    <Input
                      type="text"
                      placeholder="Enter Name"
                      value={newMember.name}
                      name="name"
                      onChange={handleNewInvite}
                    />
                  </div>
                  <div className="flex flex-col gap-3">
                    <label htmlFor="email">Email Address</label>
                    <Input
                      type="text"
                      placeholder="Enter Email Address"
                      value={newMember.email}
                      name="email"
                      onChange={handleNewInvite}
                    />
                  </div>
                  <div className="flex flex-col gap-3">
                    <label htmlFor="role">Role</label>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <button className="w-full p-2 py-3 rounded-[8px] space-x-4 mt-3 border-[#9b9ea4] border-[1px] flex justify-between bg-transparent items-center cursor-pointer">
                          <span className="text-sm">
                            {selectedOption || "Select Role"}
                          </span>
                          <img
                            src="/assets/icons/arrow-down.svg"
                            alt=""
                            className="w-3 h-3 ml-auto"
                          />
                        </button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="start"
                        className="w-[var(--radix-popper-anchor-width)] min-w-[var(--radix-popper-anchor-width)] cursor-pointer"
                      >
                        {admins.map((user, index) => (
                          <DropdownMenuItem
                            key={index}
                            className="w-full text-center px-4 py-2 hover:bg-gray-200"
                            onClick={() => {
                              setSelectedOption(user.name);
                              setNewMember((prev) => ({
                                ...prev,
                                role: user.name,
                              }));
                            }}
                          >
                            {user.name}
                          </DropdownMenuItem>
                        ))}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                  <div className="flex justify-end gap-4">
                    <Button
                      variant="outline"
                      onClick={() => setIsAddMemberOpen(false)}
                      className="border-[#023E8A] text-[#023E8A] cursor-pointer"
                    >
                      Cancel
                    </Button>
                    <Button
                      disabled={isInviteLoading}
                      type="submit"
                      className="bg-[#023E8A] border-blue-100 hover:bg-blue-500 text-white cursor-pointer"
                    >
                      {isInviteLoading && (
                        <LoaderCircleIcon
                          stroke="#023E8A"
                          style={{ animation: "spin 1s linear infinite" }}
                        />
                      )}
                      Add Member
                    </Button>
                  </div>
                </form>
              </DialogContent>
            </Dialog>
            <Dialog open={successModal} onOpenChange={setSuccessModal}>
              <DialogContent className="w-full lg:max-w-md max-w-sm p-8">
                <div className="space-y-[40px] flex flex-col items-center">
                  <DialogHeader className="text-center">
                    <DialogTitle className="text-xl font-[500] text-[#181818]">
                      Admin Added Successfully!
                    </DialogTitle>
                  </DialogHeader>
                  <img
                    src="/assets/images/Blue-check.svg"
                    alt="Success"
                    className="w-24 h-24"
                  />
                  <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-[500]">
                    You have successfully invited a new Admin. An invitation
                    email has been sent to {newMember.email || "them"} to set up
                    their account.
                  </DialogDescription>
                </div>
              </DialogContent>
            </Dialog>
          </>
        )}
      </main>
    </div>
  );
};

