export const TimeFilterDropdown = ({
  selectedOption,
  setSelectedOption,
}: {
  selectedOption: string;
  setSelectedOption: (value: string) => void;
}) => {
  const options = ["This Week", "This Month", "This Year"];
  return (
    <div className="relative">
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <div className="flex items-center space-x-2 cursor-pointer px-3 py-2">
            <p className="text-sm lg:text-base font-semibold text-[#181818]">
              {selectedOption}
            </p>
            <ChevronDown />
          </div>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          className="w-full mt-2 border rounded-lg bg-white shadow-lg space-y-2"
          align="start"
        >
          {options.map((option) => (
            <DropdownMenuItem
              key={option}
              onClick={() => setSelectedOption(option)}
              className={`px-3 py-2 space-y-2 cursor-pointer ${
                selectedOption === option
                  ? "font-bold text-white bg-gray-400"
                  : "text-gray-700"
              }`}
            >
              {option}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
};

export default page;

export type ActivityProps = {
  user_full_name: string;
  amount: number;
  date: string;
  profile_picture: string;
  booking_type: string;
};

export type MessageProps = {
  content: string;
  created_at: string;
  id: string;
  link: string;
  sender: null;
  title: string;
  type: string;
};

export type RevenueProps = {
  total_revenue: number;
  car_revenue: number;
  flight_revenue: number;
  currency: string;
};

export type UsersProps = {
  total_normal_users: number;
};

export type Bookings = {
  total_bookings: number;
};

export type BookingsProps = {
  booking_type: "flight" | "hotel" | "car";
  created_at: string;
  details: {
    arrival?: string;
    departure?: string;
    departure_date?: string;
    flight_number?: string;
  };
  email: string;
  id: string;
  specific_id: number;
  status: string;
  total_amount: number | null;
  user: string;
};

"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import {
  BarChart,
  Bar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import instance from "@/hooks/initializers/useAxiosDefaults";
import {
  ChevronDown,
  Download,
  Users,
  BookOpen,
  DollarSign,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import env from "@/config/env";
import { useAuthContext } from "@/context/AuthContext";
import { showErrorToast, showSuccessToast } from "@/utils/toasters";
import { exportStats, fetchReports } from "@/services/reports";

type Summary = {
  booking_growth_percentage: number;
  total_bookings: number;
  total_users: number;
  user_growth_percentage: number;
  total_revenue: number;
  revenue_growth_percentage: number;
};

type Breakdown = {
  label: string;
  flight_bookings: number;
  car_bookings: number;
  hotel_bookings?: number;
  flight_revenue: number;
  car_revenue: number;
  hotel_revenue?: number;
};

type Combined = {
  label: string;
  bookings: number;
  revenue: number;
};

export default function ReportsPage() {
  const APP_STATE = useAuthContext();
  const isSuperadmin = APP_STATE?.user?.isSuperuser;

  const [activeTab, setActiveTab] = useState("overview");
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingExport, setIsLoadingExport] = useState(false);
  const [overviewData, setOverviewData] = useState<Summary>();
  const [revenueBookingsData, setRevenueBookingsData] = useState<Combined[]>(
    []
  );
  const [bookingTrendsData, setBookingTrendsData] = useState<Breakdown[]>([]);
  const [selectedOption, setSelectedOption] = useState("This Week");

  const formatCurrency = useCallback((value: number) => {
    if (value >= 1_000_000) {
      return `₦${(value / 1_000_000).toFixed(1)}M`; // Changed to Naira symbol and proper formatting
    } else if (value >= 1_000) {
      return `₦${(value / 1_000).toFixed(1)}K`;
    }
    return `₦${value.toLocaleString()}`;
  }, []);

  const generateQueryParams = useCallback(() => {
    const now = new Date();
    const breakdownBaseUrl = `${env.api.admin}/reports/bookings/breakdown/?group_by=day`;
    const combinedBaseUrl = `${env.api.admin}/reports/bookings/combined/?group_by=day`;
    const summaryBaseUrl = `${env.api.admin}/reports/summary/?`;

    const params = { breakdown: "", combined: "", summary: "" };

    switch (selectedOption) {
      case "This Week": {
        const startOfWeek = new Date(now);
        startOfWeek.setDate(now.getDate() - now.getDay());
        const start = startOfWeek.toISOString().split("T")[0];
        const end = now.toISOString().split("T")[0];

        params.breakdown = `${breakdownBaseUrl}&start=${start}&end=${end}&period=week`;
        params.summary = `${summaryBaseUrl}&start=${start}&end=${end}&period=week`;
        params.combined = `${combinedBaseUrl}&start=${start}&end=${end}&period=week`;
        break;
      }
      case "This Month": {
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const start = startOfMonth.toISOString().split("T")[0];
        const end = now.toISOString().split("T")[0];

        params.breakdown = `${breakdownBaseUrl}&start=${start}&end=${end}&period=month`;
        params.summary = `${summaryBaseUrl}&start=${start}&end=${end}&period=month`;
        params.combined = `${combinedBaseUrl}&start=${start}&end=${end}&period=month`;
        break;
      }
      case "Last 3 Months":
        params.breakdown = `${breakdownBaseUrl}&months=3`;
        params.summary = `${summaryBaseUrl}&months=3`;
        params.combined = `${combinedBaseUrl}&months=3`;
        break;
      case "This Year":
        params.breakdown = `${breakdownBaseUrl}&months=12`;
        params.summary = `${summaryBaseUrl}&months=12`;
        params.combined = `${combinedBaseUrl}&months=12`;
        break;
      default:
        params.breakdown = `${breakdownBaseUrl}&months=6`;
        params.summary = `${summaryBaseUrl}&months=6`;
        params.combined = `${combinedBaseUrl}&months=6`;
        break;
    }
    return params;
  }, [selectedOption]);

  // 🔹 keep fetchAdminData same as you already have

  const fetchAdminData = useCallback(async () => {
    const { breakdown, summary, combined } = generateQueryParams();
    try {
      setIsLoading(true);
      const {
        bookingBreakdown,
        bookingsCombined,
        summary: summaryResponse,
      } = await fetchReports({ breakdown, summary, combined });

      setRevenueBookingsData(bookingsCombined);
      setOverviewData(summaryResponse);
      setBookingTrendsData(bookingBreakdown);
    } catch (error: any) {
      console.error("Error fetching data:", error);
      showErrorToast({
        message: error?.response?.data?.message || "Error displaying data",
      });
    } finally {
      setIsLoading(false);
    }
  }, [generateQueryParams, APP_STATE?.accessToken]);

  const exportData = useCallback(async () => {
    try {
      setIsLoadingExport(true);
      const response = await exportStats();

      const contentDisposition = response.headers["content-disposition"] || "";
      const fileNameMatch = contentDisposition.match(/filename\*?=(?:UTF-8''|\")?([^\";]+)/i);
      const fileName = fileNameMatch?.[1]
        ? decodeURIComponent(fileNameMatch[1].replace(/\"/g, ""))
        : "report.xlsx";
      const mimeType =
        response.headers["content-type"] ||
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

      const url = window.URL.createObjectURL(
        new Blob([response.data], { type: mimeType })
      );
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", fileName);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link); // Clean up
      window.URL.revokeObjectURL(url); // Clean up

      showSuccessToast({ message: "Download starting" });
    } catch (error: any) {
      showErrorToast({
        message: error?.response?.data?.message || "Error exporting data",
      });
      console.error("Export error:", error);
    } finally {
      setIsLoadingExport(false);
    }
  }, []);

  const processedTrendsData = useMemo(() => {
    if (!bookingTrendsData?.length) return [];

    return bookingTrendsData.map((item) => ({
      ...item,
      total_bookings:
        (item.flight_bookings || 0) +
        (item.car_bookings || 0) +
        (item.hotel_bookings || 0),
      total_revenue:
        (item.flight_revenue || 0) +
        (item.car_revenue || 0) +
        (item.hotel_revenue || 0),
      // Format label for better display
      displayLabel:
        selectedOption === "This Year"
          ? new Date(item.label).toLocaleString("en-US", { month: "long" })
          : new Date(item.label).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            }),
    }));
  }, [bookingTrendsData, selectedOption]);

  const processedCombinedData = useMemo(() => {
    if (!revenueBookingsData?.length) return [];

    return revenueBookingsData.map((item) => ({
      ...item,
      displayLabel:
        selectedOption === "This Year"
          ? new Date(item.label).toLocaleString("en-US", { month: "long" })
          : new Date(item.label).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            }),
    }));
  }, [revenueBookingsData, selectedOption]);

  useEffect(() => {
    fetchAdminData();
  }, [selectedOption]);

  const periodFilter = [
    "This Week",
    "This Month",
    "Last 3 Months",
    "This Year",
  ];

  const SkeletonLoader = () => (
    <div className="animate-pulse">
      <div className="grid gap-4 md:grid-cols-3 mb-8">
        {[1, 2, 3].map((_, index) => (
          <Card key={index} className="bg-gray-100 w-full">
            <CardContent className="p-6">
              <div className="h-4 bg-gray-300 rounded w-1/3 mb-4"></div>
              <div className="h-8 bg-gray-300 rounded w-2/3 mb-2"></div>
              <div className="h-4 bg-gray-300 rounded w-1/4"></div>
            </CardContent>
          </Card>
        ))}
      </div>
      <div className="h-[400px] bg-gray-100 rounded"></div>
    </div>
  );

  const EmptyState = ({
    message = "No data available",
  }: {
    message?: string;
  }) => (
    <div className="flex items-center justify-center h-[400px]">
      <div className="text-center">
        <div className="text-gray-400 mb-2">
          <BookOpen className="h-12 w-12 mx-auto" />
        </div>
        <p className="text-lg font-medium text-gray-500">{message}</p>
      </div>
    </div>
  );

  // if (!APP_STATE?.accessToken) {
  //   return <div>Please log in to access reports.</div>;
  // }

  return (
    <div className="flex min-h-screen p-5">
      <main className="flex-1 w-full">
        {isLoading ? (
          <SkeletonLoader />
        ) : (
          <>
            <div className="flex justify-between w-full items-center gap-4 pb-8">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline">
                    {selectedOption} <ChevronDown className="ml-2 h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent>
                  {periodFilter.map((time) => (
                    <DropdownMenuItem
                      key={time}
                      onClick={() => setSelectedOption(time)}
                    >
                      {time}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              <Button
                className={`${
                  isLoadingExport ? "bg-orange-200" : "bg-orange-500"
                } hover:bg-orange-600`}
                onClick={exportData}
                disabled={isLoadingExport}
              >
                <Download className="mr-2 h-4 w-4" />
                <span className="hidden lg:block">
                  {isLoadingExport ? "Exporting..." : "Export All Data"}
                </span>
              </Button>
            </div>

            {/* Metric Cards */}
            <div
              className={`grid gap-4 ${
                isSuperadmin ? "md:grid-cols-3" : "md:grid-cols-2"
              } mb-8`}
            >
              <Card className="bg-green-50 w-full">
                <CardContent className="p-6">
                  <div className="flex items-center gap-2">
                    <Users className="h-5 w-5" />
                    <span className="text-sm font-medium text-muted-foreground">
                      Total Users
                    </span>
                  </div>
                  <div className="mt-2">
                    <span className="text-2xl font-bold">
                      {overviewData?.total_users?.toLocaleString() ?? 0}
                    </span>
                    <span className="ml-2 text-sm text-green-600">
                      {overviewData?.user_growth_percentage ?? 0}% from last
                      period
                    </span>
                  </div>
                </CardContent>
              </Card>

              <Card className="bg-blue-50">
                <CardContent className="p-6">
                  <div className="flex items-center gap-2">
                    <BookOpen className="h-5 w-5" />
                    <span className="text-sm font-medium text-muted-foreground">
                      Total Bookings
                    </span>
                  </div>
                  <div className="mt-2">
                    <span className="text-2xl font-bold">
                      {overviewData?.total_bookings?.toLocaleString() ?? 0}
                    </span>
                    <span className="ml-2 text-sm text-blue-600">
                      {overviewData?.booking_growth_percentage ?? 0}% from last
                      period
                    </span>
                  </div>
                </CardContent>
              </Card>

              {isSuperadmin && (
                <Card className="bg-orange-50">
                  <CardContent className="p-6">
                    <div className="flex items-center gap-2">
                      <DollarSign className="h-5 w-5" />
                      <span className="text-sm font-medium text-muted-foreground">
                        Total Revenue
                      </span>
                    </div>
                    <div className="mt-2">
                      <span className="text-2xl font-bold">
                        {formatCurrency(overviewData?.total_revenue ?? 0)}
                      </span>
                      <span className="ml-2 text-sm text-orange-600">
                        {overviewData?.revenue_growth_percentage ?? 0}% from
                        last period
                      </span>
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>

            {/* Charts */}
            <Tabs
              defaultValue="overview"
              className="space-y-4"
              onValueChange={setActiveTab}
            >
              <div className="overflow-x-auto whitespace-nowrap pb-2">
                <TabsList className="min-w-max flex gap-2">
                  <TabsTrigger
                    value="overview"
                    className="flex items-center gap-2"
                  >
                    <BarChart className="h-4 w-4" />
                    Overview
                  </TabsTrigger>
                  <TabsTrigger
                    value="booking-trends"
                    className="flex items-center gap-2"
                  >
                    <LineChart className="h-4 w-4" />
                    Booking Trends
                  </TabsTrigger>
                  <TabsTrigger
                    value="user-activities"
                    className="flex items-center gap-2"
                  >
                    <Users className="h-4 w-4" />
                    User Activities
                  </TabsTrigger>
                  {isSuperadmin && (
                    <TabsTrigger
                      value="revenue-analysis"
                      className="flex items-center gap-2"
                    >
                      <DollarSign className="h-4 w-4" />
                      Revenue Analysis
                    </TabsTrigger>
                  )}
                </TabsList>
              </div>

              <Card>
                <CardContent className="pt-6">
                  {/* OVERVIEW CHART */}
                  <TabsContent value="overview" className="mt-0">
                    <h3 className="text-lg font-semibold mb-4">
                      Booking & Revenue Overview
                    </h3>
                    <div className="h-[400px]">
                      {processedCombinedData.length === 0 ? (
                        <EmptyState message="No booking or revenue data available" />
                      ) : (
                        <ResponsiveContainer width="100%" height="100%">
                          <BarChart data={processedCombinedData}>
                            <CartesianGrid
                              strokeDasharray="3 3"
                              className="stroke-muted"
                            />
                            <XAxis dataKey="displayLabel" />
                            <YAxis tickFormatter={formatCurrency} />
                            <Tooltip
                              formatter={(value, name) => [
                                typeof value === "number"
                                  ? name === "Revenue"
                                    ? formatCurrency(value)
                                    : value.toLocaleString()
                                  : value,
                                name,
                              ]}
                              contentStyle={{
                                background: "white",
                                border: "1px solid #ccc",
                                borderRadius: "8px",
                              }}
                            />
                            <Bar
                              dataKey="bookings"
                              fill="#1e40af"
                              name="Bookings"
                            />
                            {isSuperadmin && (
                              <Bar
                                dataKey="revenue"
                                fill="#f97316"
                                name="Revenue"
                              />
                            )}
                          </BarChart>
                        </ResponsiveContainer>
                      )}
                    </div>
                  </TabsContent>

                  {/* BOOKING TRENDS CHART - FIXED */}
                  <TabsContent value="booking-trends" className="mt-0">
                    <h3 className="text-lg font-semibold mb-4">
                      Booking Trends
                    </h3>
                    <div className="h-[400px]">
                      {processedTrendsData.length === 0 ? (
                        <EmptyState message="No booking trends data available" />
                      ) : (
                        <ResponsiveContainer width="100%" height="100%">
                          <LineChart data={processedTrendsData}>
                            <CartesianGrid
                              strokeDasharray="3 3"
                              className="stroke-muted"
                            />
                            <XAxis dataKey="displayLabel" />
                            <YAxis />
                            <Tooltip
                              formatter={(value) => [
                                typeof value === "number"
                                  ? value.toLocaleString()
                                  : value,
                              ]}
                              contentStyle={{
                                background: "white",
                                border: "1px solid #ccc",
                                borderRadius: "8px",
                              }}
                            />
                            <Line
                              type="monotone"
                              dataKey="flight_bookings"
                              stroke="#f97316"
                              name="Flights"
                              strokeWidth={2}
                              dot={{ r: 4 }}
                            />
                            {/* FIXED: Changed from car_bookings to hotel_bookings */}
                            <Line
                              type="monotone"
                              dataKey="hotel_bookings"
                              stroke="#22c55e"
                              name="Hotels"
                              strokeWidth={2}
                              dot={{ r: 4 }}
                            />
                            <Line
                              type="monotone"
                              dataKey="car_bookings"
                              stroke="#1e40af"
                              name="Cars"
                              strokeWidth={2}
                              dot={{ r: 4 }}
                            />
                          </LineChart>
                        </ResponsiveContainer>
                      )}
                    </div>
                  </TabsContent>

                  {/* USER ACTIVITIES CHART - IMPROVED */}
                  <TabsContent value="user-activities" className="mt-0">
                    <h3 className="text-lg font-semibold mb-4">
                      User Activities
                    </h3>
                    <div className="h-[400px]">
                      {processedTrendsData.length === 0 ? (
                        <EmptyState message="No user activity data available" />
                      ) : (
                        <ResponsiveContainer width="100%" height="100%">
                          <LineChart data={processedTrendsData}>
                            <CartesianGrid
                              strokeDasharray="3 3"
                              className="stroke-muted"
                            />
                            <XAxis dataKey="displayLabel" />
                            <YAxis />
                            <Tooltip
                              formatter={(value) => [
                                typeof value === "number"
                                  ? value.toLocaleString()
                                  : value,
                                "Total Bookings",
                              ]}
                              contentStyle={{
                                background: "white",
                                border: "1px solid #ccc",
                                borderRadius: "8px",
                              }}
                            />
                            <Line
                              type="monotone"
                              dataKey="total_bookings"
                              stroke="#f97316"
                              name="Total Bookings"
                              strokeWidth={2}
                              dot={{ r: 4 }}
                            />
                          </LineChart>
                        </ResponsiveContainer>
                      )}
                    </div>
                  </TabsContent>

                  {/* REVENUE ANALYSIS CHART - IMPROVED */}
                  {isSuperadmin && (
                    <TabsContent value="revenue-analysis" className="mt-0">
                      <h3 className="text-lg font-semibold mb-4">
                        Revenue Analysis
                      </h3>
                      <div className="h-[400px]">
                        {processedTrendsData.length === 0 ? (
                          <EmptyState message="No revenue data available" />
                        ) : (
                          <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={processedTrendsData}>
                              <CartesianGrid
                                strokeDasharray="3 3"
                                className="stroke-muted"
                              />
                              <XAxis dataKey="displayLabel" />
                              <YAxis tickFormatter={formatCurrency} />
                              <Tooltip
                                formatter={(value) => [
                                  formatCurrency(Number(value)),
                                  "Total Revenue",
                                ]}
                                contentStyle={{
                                  background: "white",
                                  border: "1px solid #ccc",
                                  borderRadius: "8px",
                                }}
                              />
                              <Line
                                type="monotone"
                                dataKey="total_revenue"
                                stroke="#eab308"
                                name="Total Revenue"
                                strokeWidth={2}
                                dot={{ r: 4 }}
                              />
                            </LineChart>
                          </ResponsiveContainer>
                        )}
                      </div>
                    </TabsContent>
                  )}
                </CardContent>
              </Card>
            </Tabs>
          </>
        )}
      </main>
    </div>
  );
}

