"use client";
import React, { useState } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu";
import { Formik, Form, Field } from "formik";
import * as Yup from "yup";
import Button from "@/components/reuseables/Button";
import { useAddFaq } from "@/hooks/api/faq";
import { useRouter } from "next/navigation";

const validationSchema = Yup.object({
  category: Yup.string().required("Category is required"),
  question: Yup.string().required("Question is required"),
  answer: Yup.string().required("Answer is required"),
});

const initialValues = {
  category: "",
  question: "",
  answer: "",
  is_active: true,
};

const Page = () => {
  const router = useRouter();
  return (
    <div className="lg:bg-transparent">
      <button
        onClick={() => router.back()}
        className="inline-flex items-center mb-4 "
        aria-label="Go back"
      >
        <img src="/assets/icons/arrow-back.svg" alt="Go back" className="" />
      </button>
      <AddComponent />
    </div>
  );
};

const AddComponent = () => {
  const router = useRouter();
  const { isSuccess, loading, onAddFaq } = useAddFaq();
  const [showModal, setShowModal] = useState(false);

  const handleSubmit = async (values: typeof initialValues) => {
    await onAddFaq({
      payload: values,
      successCallback: () => {
        setShowModal(true);
        router.push("/Dashboard/support");
      },
    });
  };

  return (
    <>
      <div className="space-y-6 py-4 px-6 rounded-[8px] bg-[#fff]">
        <h1 className="font-[600] text-[16px] lg:text-[20px] leading-[1.5] text-[#181818]">
          Add New FAQ
        </h1>
        <Formik
          initialValues={initialValues}
          validationSchema={validationSchema}
          onSubmit={handleSubmit}
        >
          {({ isValid, errors, touched, setFieldValue }) => (
            <Form>
              <div className="space-y-6">
                {/* Category Field */}
                <div className="space-y-2">
                  <label className="text-[14px] lg:text-[16px] font-[500] text-[#181818]">
                    Category:
                  </label>
                  <Dropdown
                    options={[
                      { id: 1, label: "Flights" },
                      { id: 4, label: "Car Rentals" },
                      { id: 3, label: "Account" },
                      { id: 2, label: "Stays" },
                    ]}
                    placeholder="Select category"
                    onSelect={(value) =>
                      setFieldValue("category", value?.id || "")
                    }
                  />
                  {errors.category && touched.category && (
                    <p className="text-red-500 text-sm">{errors.category}</p>
                  )}
                </div>

                {/* Question Field */}
                <div className="space-y-2">
                  <label className="text-[14px] lg:text-[16px] font-[500] text-[#181818]">
                    Question:
                  </label>
                  <Field
                    name="question"
                    type="text"
                    placeholder="Enter a frequently asked question"
                    className="w-full p-4 rounded-full outline-none border-[1px] border-[#9B9EA4] placeholder:text-[#9b9ea4] text-[16px] font-[400]"
                  />
                  {errors.question && touched.question && (
                    <p className="text-red-500 text-sm">{errors.question}</p>
                  )}
                </div>

                {/* Answer Field */}
                <div className="space-y-2">
                  <label className="text-[14px] lg:text-[16px] font-[500] text-[#181818]">
                    Answer:
                  </label>
                  <Field
                    name="answer"
                    as="textarea"
                    placeholder="Provide an answer"
                    rows={5}
                    className="w-full rounded-[8px] p-[16px] bg-[#F5F5F5] outline-none border-[1px] border-[#9B9EA4] placeholder:text-[#9b9ea4] text-[16px] font-[400]"
                  />
                  {errors.answer && touched.answer && (
                    <p className="text-red-500 text-sm">{errors.answer}</p>
                  )}
                </div>

                {/* Submit Button */}
                <Button
                  title="SUBMIT"
                  variant={isValid ? "blue" : "gray"}
                  full
                  type="submit"
                  disabled={!isValid || loading}
                  loading={loading}
                />
              </div>
            </Form>
          )}
        </Formik>
      </div>
    </>
  );
};

type DropdownOption = {
  id: number;
  label: string;
};

type DropdownProps = {
  options: DropdownOption[];
  placeholder?: string;
  onSelect: (value: DropdownOption | null) => void;
};

const Dropdown = ({ options, placeholder, onSelect }: DropdownProps) => {
  const [selectedOption, setSelectedOption] = useState<DropdownOption | null>(
    null
  );

  const handleSelect = (option: DropdownOption) => {
    setSelectedOption(option);
    onSelect(option);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button className="w-full p-4 rounded-full border-[#9b9ea4] border-[1px] flex justify-between bg-transparent">
          {selectedOption?.label || placeholder}
          <img src="/assets/icons/arrow-down.svg" alt="Dropdown Arrow" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="w-[var(--radix-popper-anchor-width)] min-w-[var(--radix-popper-anchor-width)]"
      >
        {options.map((option) => (
          <DropdownMenuItem
            key={option.id}
            className="w-full text-center px-4 py-2 hover:bg-gray-200"
            onClick={() => handleSelect(option)}
          >
            {option.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export default Page;

"use client";
import React, { useState } from "react";
import { SuccessModal } from "@/components/reuseables/SuccessModal";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { LoadingFaqSkeleton } from "@/components/molecues/support/Faq";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Accordion,
  AccordionItem,
  AccordionTrigger,
  AccordionContent,
} from "@/components/ui/accordion";
import { useDeleteFaq, useGetAllFaq } from "@/hooks/api/faq";
import Button from "@/components/reuseables/Button";
import { useRouter } from "next/navigation";

// Define the FAQ type
type Faq = {
  id: number;
  category: number;
  category_name: string;
  question: string;
  answer: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  views: number;
};

// Define the Category type
type Category = {
  id: number;
  name: string;
  name_display: string;
  description: string;
  icon: string;
  order: number;
  faqs: Faq[];
};

// Define the main response type
export type FaqResponse = {
  count: number;
  next: string | null;
  previous: string | null;
  results: Category[];
};

const Page = () => {
  const router = useRouter();
  const [selectedFaqId, setSelectedFaqId] = useState<number | null>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [refresh, setRefresh] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const { data, loading } = useGetAllFaq({ initalFetch: true, refresh });
  const { isloading, onDeleteFaq } = useDeleteFaq();

  const handleDeleteFaq = async () => {
    if (selectedFaqId !== null) {
      await onDeleteFaq({
        id: selectedFaqId,
        successCallback: async () => {
          setRefresh((prev: any) => !prev);
          setShowModal(true);
        },
      });
      setSelectedFaqId(null);
      setShowConfirmation(false);
    }
  };

  return (
    <>
      <div className="space-y-6 py-4 px-6 rounded-[8px] bg-[#fff]">
        <button
          onClick={() => router.back()}
          className="inline-flex items-center mb-4 "
          aria-label="Go back"
        >
          <img src="/assets/icons/arrow-back.svg" alt="Go back" className="" />
        </button>
        <div className="space-y-6">
          <h1 className="font-semibold text-[20px] text-[#181818]">FAQs</h1>

          <FaqTabContent
            data={data}
            loading={loading}
            selectedFaqId={selectedFaqId}
            onSelectFaq={(id) => setSelectedFaqId(id)}
          />
        </div>

        {/* Delete Button */}
        <Button
          variant="red"
          title="DELETE SELECTED"
          full
          onClick={() => setShowConfirmation(true)}
          disabled={selectedFaqId === null || isloading}
        />

        {/* Confirmation Modal */}
        {showConfirmation && (
          <Dialog
            open={showConfirmation}
            onOpenChange={() => setShowConfirmation(false)}
          >
            <DialogContent className="w-full lg:min-w-[500px] p-[30px] space-y-5 rounded-[20px]">
              <DialogHeader>
                <DialogTitle>Delete FAQ?</DialogTitle>
              </DialogHeader>
              <DialogDescription>
                Are you sure you want to delete this FAQ? This action cannot be
                undone.
              </DialogDescription>
              <div className="flex justify-between space-x-4">
                <Button
                  title={isloading ? "DELETING..." : "DELETE"}
                  variant="red"
                  onClick={handleDeleteFaq}
                  full
                  disabled={isloading}
                />
                <Button
                  title="CANCEL"
                  variant="outline-dark"
                  onClick={() => setShowConfirmation(false)}
                  full
                />
              </div>
            </DialogContent>
          </Dialog>
        )}
      </div>
    </>
  );
};

const FaqTabContent: React.FC<{
  data?: FaqResponse | null;
  loading: boolean;
  selectedFaqId: number | null;
  onSelectFaq: (id: number | null) => void;
}> = ({ data, loading, selectedFaqId, onSelectFaq }) => {
  const categories = data?.results || [];
  return (
    <div className="space-y-10">
      {loading ? (
        <LoadingFaqSkeleton />
      ) : (
        <Tabs defaultValue={categories[0]?.name_display || "Category"}>
          <TabsList className="w-full bg-transparent border-[#CDCED1] border-b-[1px] pb-[6px] rounded-none">
            {categories.map((category) => (
              <TabsTrigger
                key={category.id}
                value={category.name_display}
                className="p-2 bg-transparent shadow-transparent rounded-none border-b-[1.5px] border-transparent data-[state=active]:border-[#D72638]"
              >
                {category.name_display}
              </TabsTrigger>
            ))}
          </TabsList>
          {categories.map((category) => (
            <TabsContent key={category.id} value={category.name_display}>
              {category.faqs.length === 0 ? (
                <div className="text-center text-gray-500 mt-2.5">
                  No FAQs available in this category.
                </div>
              ) : (
                <Accordion type="single" collapsible>
                  {category.faqs.map((faq) => (
                    <AccordionItem key={faq.id} value={`faq-${faq.id}`}>
                      <AccordionTrigger>
                        <div className="flex items-center space-x-4">
                          <input
                            type="checkbox"
                            checked={selectedFaqId === faq.id}
                            onChange={(e) =>
                              onSelectFaq(e.target.checked ? faq.id : null)
                            }
                          />
                          <span>{faq.question}</span>
                        </div>
                      </AccordionTrigger>
                      <AccordionContent>{faq.answer}</AccordionContent>
                    </AccordionItem>
                  ))}
                </Accordion>
              )}
            </TabsContent>
          ))}
        </Tabs>
      )}
    </div>
  );
};

export default Page;

"use client";
import { useState, useEffect } from "react";
import ContentWrapper from "@/components/reuseables/ContentWrapper";
import React from "react";
import { useFormik } from "formik";
import { SuccessModal } from "@/components/reuseables/SuccessModal";
import * as Yup from "yup";
import {
  DetailRow,
  formatCreatedAt,
} from "@/components/molecues/support/Reuseables";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu";
import Button from "@/components/reuseables/Button";
import { useParams } from "next/navigation";
import { useGetAllEscalationLevel } from "@/hooks/api/roles";
import {
  useGetTicket,
  useGetAllEscalationReasons,
  useEscalateTicket,
} from "@/hooks/api/ticket";
import { format } from "date-fns";
import { useRouter } from "next/navigation";

const page = () => {
  const [showModal, setShowModal] = useState(false);
  const { id }: { id: string } = useParams();

  const { ticket, loadingTicket } = useGetTicket({
    TicketId: id as string,
    initalFetch: true,
    successCallback: (message) => {
      console.log(message);
    },
    errorCallback: (error) => {
      console.error(error);
    },
  });

  // if (loadingTicket) {
  //   return;
  // }

  return (
    <>
      <div>
        <ContentWrapper url="/Dashboard/support/ticket" >
          {loadingTicket ? (
            <div className="flex justify-center items-center h-full w-full ">
              <LoadingState />
            </div>
          ) : (
            <div className="bg-[#fff] shadow-md lg:rounded-[20px]">
              <EscalateDetails
                data={ticket}
                showModal={showModal}
                setShowModal={setShowModal}
              />
            </div>
          )}
        </ContentWrapper>
      </div>

      {showModal && (
        <SuccessModal
          title="Ticket escalated Successfully"
          description="You have successfully escalated this ticket."
          onClose={() => setShowModal(false)}
        />
      )}
    </>
  );
};

const EscalateDetails = ({ data, showModal, setShowModal }: any) => {
  return (
    <div className="p-[40px] space-y-[24px]">
      <div>
        <h3 className="font-[500] lg:text-[16px] text-[14px] text-[#181818]">
          {data?.created_at
            ? format(
                new Date(data.created_at),
                "EEEE do 'of' MMM.yyyy | hh:mmaaa"
              )
            : "Date not available"}
        </h3>
      </div>
      <div>
        <h1 className="font-[600] text-[16px] lg:text-[28px] text-[#181818]">
          Escalate Issue #{data?.ticket_id}
        </h1>
      </div>
      <TicketDetails ticket={data} />
      <CustomerInfo user={data?.user} />
      <Selections
        id={data?.id}
        showModal={showModal}
        setShowModal={setShowModal}
      />
    </div>
  );
};

const Selections = ({ id, showModal, setShowModal }: any) => {
  const { escalating, onEscalateTicket } = useEscalateTicket();
  const { Leveldata, Levelloading } = useGetAllEscalationLevel({
    initalFetch: true,
  });
  const [selectedEmail, setSelectedEmail] = useState("");

  const handleDropdownSelect = (option: any) => {
    setSelectedEmail(option?.email || "");
  };
  const router = useRouter();

  const formik = useFormik({
    initialValues: {
      escalation_level: "",
      escalation_reason: "",
      escalation_note: "",
      escalation_response_time: "",
    },
    validationSchema: Yup.object({
      escalation_level: Yup.string().required("Escalation level is required"),
      escalation_reason: Yup.string().required("Reason is required"),
      escalation_note: Yup.string()
        .required("Note is required")
        .max(200, "Note cannot exceed 200 characters"),
      escalation_response_time: Yup.string().required(
        "Response time is required"
      ),
    }),
    onSubmit: (values) => {
      const payload = {
        escalation_role: values.escalation_level,
        escalation_reason: values.escalation_reason,
        escalation_note: values.escalation_note,
        escalation_response_time: values.escalation_response_time,
      };

      onEscalateTicket({
        TicketId: id,
        payload,
        successCallback: () => {
          setShowModal(true);
          router.push("/Dashboard/support/ticket/escalates");
        },
      });
    },
  });
  console.log(Leveldata);

  return (
    <>
      <form
        onSubmit={formik.handleSubmit}
        className="space-y-6 mt-[24px]"
        noValidate
      >
        <div className="space-y-10">
          <div className="space-y-6">
            <h1 className="text-[16px] font-[500] text-[#181818]">
              Department:
            </h1>
            <Dropdown
              options={Leveldata || []}
              placeholder="Select Department"
              onSelect={(option) => {
                formik.setFieldValue("escalation_level", option.id);
                handleDropdownSelect(option); // Ensure the option is passed to update the email
              }}
            />
            {formik.touched.escalation_level &&
              formik.errors.escalation_level && (
                <p className="text-red-500 text-sm">
                  {formik.errors.escalation_level}
                </p>
              )}
          </div>

          <div className="space-y-6">
            <h1 className="text-[16px] font-[500] text-[#181818]">
              Reason for Escalation:
            </h1>
            <input
              type="text"
              name="escalation_reason"
              placeholder="Provide reason for escalation"
              className="w-full p-4 rounded-[8px] bg-[#f5f5f5] placeholder:text-[#9b9ea4] text-[16px] font-[400]"
              value={formik.values.escalation_reason}
              onChange={formik.handleChange}
            />
            {formik.touched.escalation_reason &&
              formik.errors.escalation_reason && (
                <p className="text-red-500 text-sm">
                  {formik.errors.escalation_reason}
                </p>
              )}
          </div>

          <div className="space-y-6">
            <h1 className="text-[16px] font-[500] text-[#181818]">
              Escalation Note:
            </h1>
            <textarea
              name="escalation_note"
              maxLength={200}
              placeholder="Please provide additional information on what has been attempted so far"
              className="w-full p-4 rounded-[8px] bg-[#f5f5f5] placeholder:text-[#9b9ea4] text-[16px] font-[400]"
              value={formik.values.escalation_note}
              onChange={formik.handleChange}
            />
            {formik.touched.escalation_note &&
              formik.errors.escalation_note && (
                <p className="text-red-500 text-sm">
                  {formik.errors.escalation_note}
                </p>
              )}
          </div>

          <div className="space-y-6">
            <h1 className="text-[16px] font-[500] text-[#181818]">
              Escalation Response Time:
            </h1>
            <MiniDropdown
              options={[
                { id: "1hr", label: "1 Hour (Emergency)" },
                { id: "4hrs", label: "4 Hours (Urgent)" },
                { id: "24hrs", label: "24 Hours (High priority)" },
              ]}
              placeholder="Select response time"
              onSelect={(option) =>
                formik.setFieldValue("escalation_response_time", option?.id)
              }
            />
            {formik.touched.escalation_response_time &&
              formik.errors.escalation_response_time && (
                <p className="text-red-500 text-sm">
                  {formik.errors.escalation_response_time}
                </p>
              )}
          </div>

          <div>
            <Button
              title="ESCALATE REQUEST"
              variant={
                !formik.isValid || escalating || !formik.dirty ? "gray" : "blue"
              }
              full
              icon="/assets/icons/white-caution.svg"
              iconPosition="left"
              disabled={!formik.isValid || escalating || !formik.dirty}
              loading={escalating}
              size="16"
              weight="600"
              className="transition-all ease-in-out"
            />
          </div>
        </div>
      </form>
    </>
  );
};

