        <div className="flex space-x-1">
          <div className="w-1/2">
            <p className="font-inter font-[400] text-[14px] leading-[100%] tracking-[0%] ">
              Phone Number
            </p>
          </div>
          <div className="w-1/2">
            <p className="font-inter font-[500] text-[15px] break-all">
              {mobile_number || "N/A"}
            </p>
          </div>
        </div>
        <div className="flex space-x-1">
          <div className="w-1/2">
            <p className="font-inter font-[400] text-[14px] leading-[100%] tracking-[0%] ">
              Email Address
