import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, Plus, LoaderCircleIcon } from "lucide-react";
import { FC } from "react";
import { useRouter } from "next/navigation";
import Loading from "@/app/Dashboard/admin/loading";
import { showErrorToast } from "@/utils/toasters";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogHeader,
  DialogDescription,
} from "@/components/ui/dialog";
import { removeUsersFromRole } from "@/services/admin";

interface Role {
  id: string;
  name: string;
  description: string;
  assigned_users: any[];
  current_permission_group_slugs: string[];
  is_superuser: boolean;
  created_by: string;
  invited_users: any[];
}
interface RoleAssignmentProps {
  roles: Role[]; // Array of roles to display
  onCreateRoleOpen: () => void; // Callback to open Create Role modal
  onAddMemberOpen: () => void;
  isLoading?: boolean;
  revokeInvite: (id: string, email: string) => void;
  setAdminDetails: React.Dispatch<React.SetStateAction<Role[]>>;
}
const RoleAssignment: FC<RoleAssignmentProps> = ({
  onAddMemberOpen,
  roles,
  isLoading,
  revokeInvite,
  setAdminDetails,
}) => {
  const [showSuccessRemoveModal, setShowSuccessRemoveModal] = useState(false);
  const [showConfirmRemoveModal, setShowConfirmRemoveModal] = useState(false);
  const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);
  const [selectedUserEmail, setSelectedUserEmail] = useState<string | null>(
    null
  );

  const currentRole = roles.find(
    (role) => String(role.id) === String(selectedRoleId)
  );
  const route = useRouter();
  const [loadingRemove, setLoadingRemove] = useState<{
    [key: string]: boolean;
  }>({});

  const ManageUsers = (roleId: string) => {
    const role = roles.find((r) => r.id === roleId);
    if (!role) return;
    const isSuperAdmin = role.name === "Super Admin" || role.is_superuser;
    route.push(
      isSuperAdmin
        ? `/Dashboard/admin/manage-super-admin/${roleId}/`
        : `/Dashboard/admin/manage-user/${roleId}/`
    );
  };

  const handleRemoveUser = async (roleId: string, userEmail: string) => {
    try {
      setLoadingRemove((prev) => ({ ...prev, [userEmail]: true }));

      await removeUsersFromRole(roleId, userEmail);
      const updatedRoles = roles.map((role) =>
        role.id === roleId
          ? {
              ...role,
              assigned_users: role.assigned_users.filter(
                (user) => user.email !== userEmail
              ),
            }
          : role
      );

      setAdminDetails(updatedRoles);
      setShowConfirmRemoveModal(false);
      setShowSuccessRemoveModal(true);
    } catch (error: any) {
      console.log(error);
      showErrorToast({
        message: error?.response?.data?.message || "Failed to remove user.",
      });
    } finally {
      setSelectedRoleId(null);
      setSelectedUserEmail(null);
      setLoadingRemove((prev) => ({ ...prev, [userEmail]: false }));
    }
  };

  const [searchQuery, setSearchQuery] = useState("");

  const filteredRoles = useMemo(() => {
    return roles.filter((role) => {
      const query = searchQuery.toLowerCase();
      const isRoleNameMatch = role.name.toLowerCase().includes(query);
      const isAssignedUserMatch = role?.assigned_users?.some((user) =>
        (user.name || "").toLowerCase().includes(query)
      );
      return isRoleNameMatch || isAssignedUserMatch;
    });
  }, [roles, searchQuery]);

  return (
    <>
      <div className="p-4 lg:p-0">
        <div className="flex justify-between items-center md:gap-32 gap-6">
          <div className="relative w-full">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search roles..."
              className="pl-9 rounded-4xl"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Button
            className="bg-[#023E8A] hover:bg-blue-800 cursor-pointer"
            onClick={onAddMemberOpen}
          >
            <Plus className="md:mr-2 mr-0 h-4 w-4" />
            <span className="hidden md:block">Invite New Member</span>
          </Button>
        </div>
        {isLoading ? (
          <Loading />
        ) : (
          filteredRoles.map((role, index) => (
            <div key={index} className="space-y-3 pt-5 pb-12">
              <div>
                <h3 className="text-lg font-medium">{role.name || ""}</h3>
                <p className="text-muted-foreground text-sm pt-2 py-3">
                  {role.description || ""}
                </p>
                <p className="pt-2 text-[16px]">
                  Assigned users ({role.assigned_users?.length})
                </p>
              </div>
              {role.assigned_users?.map((assigned, i) => (
                <div
                  className=" flex justify-between w-full lg:items-center align-top lg:align-middle"
                  key={i}
                >
                  <div className="flex flex-col justify-normal ">
                    <p className="font-medium">
                      {assigned?.name || assigned?.email || "Unnamed User"}
                    </p>
                    <p className="text-slate-600">{assigned?.email}</p>
                  </div>

                  {role.name !== "Super Admin" && (
                    <Button
                      variant="link"
                      className={`text-red-600
                       hover:text-red-800 p-0 cursor-pointer`}
                      onClick={() => {
                        setSelectedRoleId(role.id);
                        setSelectedUserEmail(assigned.email);
                        setShowConfirmRemoveModal(true);
                        setSelectedRoleId(role.id);
                      }}
                      disabled={loadingRemove[assigned?.email]}
                    >
                      {loadingRemove[assigned.email] ? "Removing" : "Remove"}
                    </Button>
                  )}
                </div>
              ))}
              {role.invited_users?.map((invited, i) => (
                <div
                  className=" flex justify-between w-full items-center"
                  key={i}
                >
                  <p className="font-medium">{invited.name || ""}</p>
                  <Button
                    variant="link"
                    className={`text-blue-600
                      hover:text-blue-800 p-0`}
                  >
                    Invited
                  </Button>
                  <Button
                    onClick={() => revokeInvite(role.id, invited.email)}
                    variant="link"
                    className={` text-green-600
                      hover:text-green-800 p-0`}
                  >
                    Revoke Invite
                  </Button>
                </div>
              ))}
              <Button
                className="w-full h-12 bg-[#CCD8E8] text-[#023E8A] hover:bg-muted/80 cursor-pointer"
                onClick={() => ManageUsers(role.id)}
                disabled={role.assigned_users.length === 0}
              >
                Manage Users
              </Button>
            </div>
          ))
        )}

        {/* MODAL TO SHOW REMOVE SUCCESSFUL  */}
        <Dialog
          open={showSuccessRemoveModal}
          onOpenChange={setShowSuccessRemoveModal}
        >
          <DialogContent className="w-full lg:max-w-sm max-w-sm p-8">
            <div className="flex flex-col items-center">
              <DialogHeader className="text-center">
                <DialogTitle className="text-xl font-[500] text-[#181818]"></DialogTitle>
              </DialogHeader>
              <img
                src="/assets/icons/blue-success.svg"
                alt="Success"
                className="w-20 h-20 my-6"
              />
              <DialogDescription className="lg:text-lg text-[14px] text-gray-700 text-center px-4 font-bold">
                Users Removed Successfully
              </DialogDescription>
            </div>
          </DialogContent>
        </Dialog>
        {/* MODAL TO CONFIRM DELETE OR REMOVE ADMIN  */}
        <Dialog
          open={showConfirmRemoveModal}
          onOpenChange={setShowConfirmRemoveModal}
        >
          <DialogContent className="w-full lg:max-w-lg max-w-sm p-4">
            <div className="space-y-[40px] flex flex-col items-center">
              <DialogHeader className="text-left">
                <DialogTitle className="text-xl font-bold text-[#181818]">
                  Confirm Remove Users?
                </DialogTitle>
              </DialogHeader>
              <DialogDescription className="lg:text-base text-[12px] text-gray-700 text-left px-4 font-[500]">
                You are about to remove the selected users from{" "}
                {currentRole?.name} role. They will no longer have access to
                these role permissions. Do you want to proceed?
              </DialogDescription>
            </div>
            <div className="flex items-center gap-2 justify-end pt-5">
              <Button
                className="border text-black border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
                onClick={() => setShowConfirmRemoveModal(false)}
              >
                Cancel
              </Button>

              <Button
                className="bg-[#023E8A] p-2 px-4 hover:bg-blue-700 cursor-pointer"
                onClick={() => {
                  if (selectedRoleId && selectedUserEmail) {
                    handleRemoveUser(selectedRoleId, selectedUserEmail);
                  }
                }}
              >
                {selectedUserEmail && loadingRemove[selectedUserEmail] ? (
                  <LoaderCircleIcon
                    stroke="#ffffff"
                    className="animate-spin mr-2 w-4 h-4"
                  />
                ) : null}
                Yes, Proceed
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </>
  );
};
export default RoleAssignment;

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  Plus,
  LucideMoreVertical,
  LoaderCircleIcon,
} from "lucide-react";
import { FC, JSX, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Loading from "@/app/Dashboard/admin/loading";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@radix-ui/react-dialog";
import { DialogHeader } from "@/components/ui/dialog";

interface Role {
  id: string;
  name: string;
  description: string;
  assigned_users: any[]; // Array of assigned users
  current_permission_group_slugs: any[];
  is_superuser: boolean;
  created_by: string;
  invited_users: any[];
}

interface RoleManagementProps {
  roles: Role[];
  onCreateRoleOpen: () => void;
  isLoading: boolean;
  onStartEdit: (role: Role) => void;
  roleToDelete: string | null;
  setRoleToDelete: (roleId: string | null) => void;
  showConfirmModal: boolean;
  setShowConfirmModal: (open: boolean) => void;
  confirmDeleteRole: () => void;
  successDeleteModal: boolean;
  setSuccessDeleteModal: (open: boolean) => void;
  isDeleteLoading: boolean;
}

const RoleManagement: FC<RoleManagementProps> = ({
  roles,
  onCreateRoleOpen,
  isLoading,
  onStartEdit,
  roleToDelete,
  setRoleToDelete,
  showConfirmModal,
  setShowConfirmModal,
  confirmDeleteRole,
  successDeleteModal,
  setSuccessDeleteModal,
  isDeleteLoading,
}): JSX.Element => {
  const router = useRouter();
  const [openActionRoleId, setOpenActionRoleId] = useState<string | null>(null);

  const toggleActionMenu = (roleId: string) => {
    setOpenActionRoleId((prev) => (prev === roleId ? null : roleId));
  };

  const ManageUsers = (roleId: string) => {
    const role = roles.find((r) => r.id === roleId);
    if (!role) return;
    const isSuperAdmin = role.name === "Super Admin" || role.is_superuser;
    router.push(
      isSuperAdmin
        ? `/Dashboard/admin/manage-super-admin/${roleId}/`
        : `/Dashboard/admin/manage-user/${roleId}/`
    );
  };
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    if (successDeleteModal) {
      const timeout = setTimeout(() => {
        setSuccessDeleteModal(false);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [successDeleteModal]);
  return (
    <div className="p-3 lg:p-0">
      {/* Header Section */}
      <div className="flex justify-between items-center md:gap-32 gap-6">
        {/* Search Input */}
        <div className="relative w-full">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search roles..."
            className="pl-9 rounded-4xl"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {/* Create Role Button */}
        <div className="flex items-center gap-2 justify-normal">
          <Button
            className="bg-[#023E8A] hover:bg-blue-800 cursor-pointer"
            onClick={onCreateRoleOpen}
          >
            <Plus className="md:mr-2 mr-0 h-4 w-4" />
            <span className="hidden md:block">Create New Role</span>
          </Button>
        </div>
      </div>

      {/* Table Section */}
      <div className="border rounded-lg mt-3 w-full overflow-x-auto">
        <table className="w-full lg:mb-32 mb-12">
          <thead>
            <tr className="bg-muted">
              <th className="text-left p-3 font-medium md:text-sm text-xs">
                Role Name
              </th>
              <th className="text-left p-3 font-medium md:text-sm text-xs">
                Description
              </th>
              <th className="text-left p-3 font-medium md:text-sm text-xs text-nowrap">
                Assigned Users
              </th>
              <th className="text-left p-3 font-medium md:text-sm text-xs pl-8">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="text-xs md:text-base">
            {/* Loading State */}
            {isLoading ? (
              <tr>
                <td colSpan={4} className="p-4 text-center">
                  <Loading />
                </td>
              </tr>
            ) : roles.length === 0 ? (
              // No Roles Found
              <tr>
                <td
                  colSpan={4}
                  className="p-4 text-center text-muted-foreground"
                >
                  No roles found.
                </td>
              </tr>
            ) : (
              // Render Roles
              roles
                .filter((r) =>
                  r.name.toLowerCase().includes(searchQuery.toLowerCase())
                )
                .map((role) => (
                  <tr className="border-t" key={role.id}>
                    <td className="pl-3 p-3 md:text-base text-xs capitalize">
                      {role.is_superuser ? "Super Admin" : role.name}
                    </td>
                    <td className="pl-3 p-3 capitalize text-muted-foreground md:text-base text-xs">
                      {role.is_superuser
                        ? "Manage overall dashboard and settings"
                        : role.description}
                    </td>
                    <td className="pl-3 p-3 md:text-base text-xs">
                      {role.assigned_users.length} User
                      {role.assigned_users.length > 1 && "s"}
                    </td>
                    <td className="lg:pl-12 relative">
                      <LucideMoreVertical
                        className="cursor-pointer w-4"
                        onClick={() => toggleActionMenu(role.id)}
                      />

                      {openActionRoleId === role.id && (
                        <div className="absolute bg-white rounded-lg p-3 flex flex-col w-[150px]  border-[1px] border-white h-fit top-10 right-10 z-[99999] shadow-lg items-start">
                          {/* Edit Button */}
                          <p
                            className="cursor-pointer text-xs md:text-base pb-3"
                            onClick={() => {
                              onCreateRoleOpen();
                              onStartEdit(role);
                              setOpenActionRoleId(null);
                            }}
                          >
                            Edit
                          </p>

                          {/* Manage Users Button */}
                          <p
                            className=" cursor-pointer text-xs md:text-base pb-3"
                            onClick={() => {
                              ManageUsers(role.id);
                              setOpenActionRoleId(null);
                            }}
                          >
                            Manage User
                          </p>
                          {/* Delete Roles Button  */}
                          {role.name !== "Super Admin" && (
                            <p
                              className=" cursor-pointer text-xs md:text-base"
                              onClick={() => {
                                setRoleToDelete(role.id);
                                setOpenActionRoleId(null);
                                setShowConfirmModal(true);
                              }}
                            >
                              Delete
                            </p>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
            )}
          </tbody>
        </table>
      </div>

      {/* CONFIRM DELETE MODAL  */}
      <Dialog open={showConfirmModal} onOpenChange={setShowConfirmModal}>
        <DialogContent className="w-full lg:max-w-lg max-w-sm p-4 m-auto absolute top-1/3 left-1/3 bg-white rounded-2xl shadow-2xl">
          <div className="lg:space-y-[40px] space-y-3 flex flex-col items-center">
            <DialogHeader className="text-left">
              <DialogTitle className="text-lg font-bold text-[#181818]">
                Delete Role?
              </DialogTitle>
            </DialogHeader>
            <DialogDescription className="lg:text-base text-[12px] text-[#4E4F52] text-left px-4">
              You are about to delete the "
              {roles.find((r) => r.id === roleToDelete)?.name || "this role"}".
              This action cannot be undone and all permissions for this role
              will be permanently cleared. Are you sure you want to proceed?
            </DialogDescription>
          </div>
          <div className="flex items-center gap-2 justify-end lg:pt-5 pt-2">
            <Button
              className="border text-black border-[#023E8A] p-2 bg-transparent hover:bg-transparent cursor-pointer"
              onClick={() => {
                setShowConfirmModal(false);
                setRoleToDelete(null);
              }}
            >
              Cancel
            </Button>
            <Button
              onClick={() => {
                confirmDeleteRole();
              }}
              className="bg-[#D72638] p-2 px-4 hover:bg-red-700 cursor-pointer flex items-center"
            >
              {isDeleteLoading && (
                <LoaderCircleIcon
                  className="w-5 h-5 mr-2 text-white"
                  style={{
                    animation: "spin 1s linear infinite",
                  }}
                />
              )}
              Yes, Proceed
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* SUCCESS MODAL DELETE */}
      <Dialog open={successDeleteModal} onOpenChange={setSuccessDeleteModal}>
        <DialogContent className="w-full max-w-sm p-8 m-auto absolute top-1/3 left-1/3 bg-white rounded-2xl shadow-2xl">
          <div className="space-y-[40px] flex flex-col items-center  ">
            <img
              src="/assets/images/Blue-check.svg"
              alt="Success"
              className="w-24 h-24 "
            />
            <DialogHeader className="text-center">
              <DialogTitle className="text-xl font-[500] text-[#181818]">
                Role Deleted Successfully!
              </DialogTitle>
            </DialogHeader>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default RoleManagement;

"use client";
import React, { useState, useEffect } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Table,
  TableHeader,
  TableRow,
  TableCell,
  TableBody,
} from "@/components/ui/table";
import { BookingTableDropdown } from "./reuseables";

// Define the interface for filter props
interface FilterProps {
  searchTerm: string;
  selectedOption: string;
  selectedStartDate?: string;
  selectedEndDate?: string;
  selectedDate?: string;
  currency: string;
}

// Define the interface for component props
interface BookingTableProps {
  title: string;
  filterProps: FilterProps;
  bookings: any[] | null | undefined; // can be null or undefined
  loading: boolean;
  onLoadMore: () => void;
  hasMore: boolean;
}

const BookingTable: React.FC<BookingTableProps> = ({
  title,
  filterProps,
  bookings = [], // default to empty array
  loading,
  onLoadMore,
  hasMore,
}) => {
  
  const [activeSubTab, setActiveSubTab] = useState<string>("ongoing");
  const [filteredData, setFilteredData] = useState<any[]>([]);

  const styling =
    "h-full data-[state=active]:text-[#181818] data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:rounded-none data-[state=active]:border-b-[3px] data-[state=active]:border-b-[#181818] data-[state=active]:mb-0 flex items-center justify-center cursor-pointer bg-transparent shadow-none rounded-none text-[18px] text-[#4E4F52] font-[400] ";

  /**
   * Filter data based on active sub-tab
   * This runs whenever bookings or the selected tab changes
   */
  useEffect(() => {
    const safeBookings = Array.isArray(bookings) ? bookings : [];

    const filtered = safeBookings.filter((item) => {
      const status = item.booking_status?.toLowerCase();
      switch (activeSubTab) {
        case "ongoing":
          return status === "pending" || status === "confirmed";
        case "completed":
          return status === "completed";
        case "cancelled":
          return status === "cancelled";
        default:
          return true;
      }
    });

    setFilteredData(filtered);
  }, [bookings, activeSubTab]);


  const formatAmount = (amount: string | number) => {
    const numAmount = typeof amount === "string" ? parseFloat(amount) : amount;
    if (filterProps.currency === "USD") {
      return `$${numAmount.toFixed(2)}`;
    }
    // Convert USD to NGN roughly for demo purposes
    return `₦${(numAmount * 1500).toLocaleString()}`;
  };

  /**
   * Format date into dd/mm/yyyy
   */
  const formatDate = (dateString: string) => {
    if (!dateString) return "N/A";
    const date = new Date(dateString);
    return date.toLocaleDateString("en-GB");
  };

  /**
   * Format stay dates
   */
  const formatStayDates = (checkIn: string, checkOut: string) => {
    if (!checkIn || !checkOut) return "N/A";
    return `${formatDate(checkIn)} - ${formatDate(checkOut)}`;
  };

  /**
   * Calculate nights between two dates
   */
  const calculateNights = (checkIn: string, checkOut: string) => {
    if (!checkIn || !checkOut) return 0;
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    const diffTime = Math.abs(end.getTime() - start.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getStatusStyling = (status: string) => {
    switch (status?.toLowerCase()) {
      case "completed":
      case "confirmed":
      case "paid":
        return "text-[#2D9C5E] border-[#2D9C5E] bg-[#2D9C5E1A]";
      case "cancelled":
      case "failed":
        return "text-[#E74C3C] border-[#E74C3C] bg-[#E74C3C1A]";
      case "pending":
      default:
        return "text-[#EFB608] border-[#EFB608] bg-[#EFB60833]";
    }
  };

  return (
    <div className="bg-white border border-gray-300 rounded-lg py-4">
      <h2 className="text-lg font-semibold px-4 mb-4">{title}</h2>

      <Tabs value={activeSubTab} onValueChange={setActiveSubTab}>
        <TabsList className="flex space-x-6 items-center bg-transparent shadow-none rounded-none pb-0">
          <TabsTrigger value="ongoing" className={styling}>
            Ongoing
          </TabsTrigger>
          <TabsTrigger value="completed" className={styling}>
            Completed
          </TabsTrigger>
          <TabsTrigger value="cancelled" className={styling}>
            Cancelled
          </TabsTrigger>
        </TabsList>

        <div className="overflow-x-auto border-t-[1px] border-[#4E4F52]">
          <Table className="border-none border-collapse min-w-[600px]">
            <TableHeader className="bg-[#f5f5f5]">
              <TableRow className="border-none">
                {[
                  "ID",
                  "Hotel Name",
                  "Guest Name",
                  "Booked On",
                  "Check-in - Check-out",
                  "Nights",
                  "Room Type",
                  "Total Amount",
                  "Payment Status",
                  "Booking Status",
                  "Actions",
                ].map((header) => (
                  <TableCell
                    key={header}
                    className="font-[400] text-[#181818] text-[14px] py-5 px-4"
                    style={{ minWidth: "192.5px" }}
                  >
                    {header}
                  </TableCell>
                ))}
              </TableRow>
            </TableHeader>

            <TableBody className="px-4">
              {/* Loading Skeleton */}
              {loading ? (
                Array.from({ length: 5 }).map((_, index) => (
                  <TableRow key={`skeleton-${index}`}>
                    {Array.from({ length: 11 }).map((_, cellIndex) => (
                      <TableCell
                        key={cellIndex}
                        className="py-3 px-4"
                        style={{ minWidth: "192.5px" }}
                      >
                        <div className="animate-pulse bg-gray-200 h-4 rounded"></div>
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : filteredData.length > 0 ? (
                <>
                  {filteredData.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {item.reference || "N/A"}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {item.hotel_name || "N/A"}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {item.customer_details?.name &&
                        item.customer_details?.surname
                          ? `${item.customer_details.name} ${item.customer_details.surname}`
                          : "N/A"}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {/* Booked On - Replace with actual booked date when available */}
                        N/A
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {formatStayDates(item.check_in, item.check_out)}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {calculateNights(item.check_in, item.check_out)}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {item.rooms?.length > 0
                          ? item.rooms[0].room_type || "Standard"
                          : "Standard"}
                      </TableCell>
                      <TableCell className="py-3 px-4 text-sm text-[#181818]">
                        {item.total_amount
                          ? formatAmount(item.total_amount)
                          : "N/A"}
                      </TableCell>
                      <TableCell className="py-3 px-4">
                        <div
                          className={`border rounded-[12px] text-[14px] font-[400] p-[8px] w-fit ${getStatusStyling(
                            item.payment_status
                          )}`}
                        >
                          {item.payment_status || "PENDING"}
                        </div>
                      </TableCell>
                      <TableCell className="py-3 px-4">
                        <div
                          className={`border rounded-[12px] text-[14px] font-[400] p-[8px] w-fit ${getStatusStyling(
                            item.booking_status
                          )}`}
                        >
                          {item.booking_status || "PENDING"}
                        </div>
                      </TableCell>
                      <TableCell className="py-3 px-4 cursor-pointer">
                        <BookingTableDropdown
                          booking_refrence={
                            item.reference || item.booking_reference || item.id
                          }
                        />
                      </TableCell>
                    </TableRow>
                  ))}

                  {/* Load More Button */}
                  {hasMore && !loading && (
                    <TableRow>
                      <TableCell colSpan={11} className="text-center py-4">
                        <button
                          onClick={onLoadMore}
                          disabled={loading}
                          className="px-4 py-2 bg-[#023E8A] text-white rounded hover:bg-[#023E8A]/90 disabled:opacity-50"
                        >
                          Load More
                        </button>
                      </TableCell>
                    </TableRow>
                  )}
                </>
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={11}
                    className="text-center py-8 text-[#4E4F52]"
                  >
                    No bookings found matching your criteria
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      </Tabs>
    </div>
  );
};

export default BookingTable;

"use client";
import React, { useState, useMemo } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Table,
  TableHeader,
  TableRow,
  TableCell,
  TableBody,
} from "@/components/ui/table";
import { BookingTableDropdown } from "./reuseables";

interface FilterProps {
  searchTerm: string;
  selectedOption: string;
  selectedStartDate?: string;
  selectedEndDate?: string;
  selectedDate?: string;
  currency: string;
}

interface CarBookingsProps {
  title: string;
  filterProps: FilterProps;
  bookings: any[];
  loading: boolean;
  onLoadMore: () => void;
  hasMore: boolean;
}

const CarBookings: React.FC<CarBookingsProps> = ({
  title,
  filterProps,
  bookings = [],
  loading,
  onLoadMore,
  hasMore,
}) => {
  const [activeSubTab, setActiveSubTab] = useState<string>("ongoing");

  const styling =
    "h-full data-[state=active]:text-[#181818] data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:rounded-none data-[state=active]:border-b-[3px] data-[state=active]:border-b-[#181818] data-[state=active]:mb-0 flex items-center justify-center cursor-pointer bg-transparent shadow-none rounded-none text-[18px] text-[#4E4F52] font-[400] ";

  // Filter bookings by active tab
  const filteredData = useMemo(() => {
    if (!Array.isArray(bookings)) return [];

    return bookings.filter((item) => {
      const status = item.booking_status?.toLowerCase();
      switch (activeSubTab) {
        case "ongoing":
          return status === "pending" || status === "confirmed";
        case "completed":
          return status === "completed";
        case "cancelled":
          return status === "cancelled";
        default:
          return true;
      }
    });
  }, [bookings, activeSubTab]);

  // Format amount
  const formatAmount = (amount: string | number) => {
    const numAmount = typeof amount === "string" ? parseFloat(amount) : amount;
    return filterProps.currency === "USD"
      ? `$${numAmount.toFixed(2)}`
      : `₦${numAmount.toLocaleString()}`;
  };

  // Format date
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-GB");
  };

  // Status styling
  const getStatusStyling = (status: string) => {
    switch (status?.toLowerCase()) {
      case "completed":
      case "confirmed":
      case "paid":
        return "text-[#2D9C5E] border-[#2D9C5E] bg-[#2D9C5E1A]";
      case "cancelled":
      case "failed":
        return "text-[#E74C3C] border-[#E74C3C] bg-[#E74C3C1A]";
      case "pending":
      default:
        return "text-[#EFB608] border-[#EFB608] bg-[#EFB60833]";
    }
  };

  // Helper: get passenger name
  const getPassengerName = (passenger: any) => {
    if (!passenger) return "N/A";
    return `${passenger.first_name} ${passenger.last_name}`;
  };

  return (
    <div className="bg-white border border-gray-300 rounded-lg py-4">
      <h2 className="text-lg font-semibold px-4 mb-4">{title}</h2>

      {/* Tabs for status filters */}
      <Tabs value={activeSubTab} onValueChange={setActiveSubTab}>
        <TabsList className="flex space-x-6 items-center bg-transparent shadow-none rounded-none pb-0">
          <TabsTrigger value="ongoing" className={styling}>
            Ongoing
          </TabsTrigger>
          <TabsTrigger value="completed" className={styling}>
            Completed
          </TabsTrigger>
          <TabsTrigger value="cancelled" className={styling}>
            Cancelled
          </TabsTrigger>
        </TabsList>

        <div className="overflow-x-auto border-t-[1px] border-[#4E4F52]">
          <Table className="border-none border-collapse min-w-[600px]">
            <TableHeader className="bg-[#f5f5f5]">
              <TableRow className="border-none">
                {[
                  "ID",
                  "Booking Reference",
                  "Passenger Name",
                  "Pickup Location",
                  "Dropoff location",
                  "Booked On",
                  "Car Type",
                  "Total Amount",
                  "Payment Status",
                  "Booking Status",
                  "Actions",
                ].map((header) => (
                  <TableCell
                    key={header}
                    className="font-[500] text-[#181818] text-[14px] py-5 px-4"
                    style={{ minWidth: "192.5px" }}
                  >
                    {header}
                  </TableCell>
                ))}
              </TableRow>
            </TableHeader>

            <TableBody className="px-4">
              {loading ? (
                // Loading Skeleton
                Array.from({ length: 5 }).map((_, index) => (
                  <TableRow key={`skeleton-${index}`}>
                    {Array.from({ length: 11 }).map((_, cellIndex) => (
                      <TableCell
                        key={cellIndex}
                        className="py-3 px-4"
                        style={{ minWidth: "192.5px" }}
                      >
                        <div className="animate-pulse bg-gray-200 h-4 rounded"></div>
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : bookings.length > 0 ? (
                <>
                  {bookings.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-4">
                        {item.booking_reference || "N/A"}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-4">
                        {item.id
                          ? String(item.id).substring(0, 8) + "..."
                          : "N/A"}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-4">
                        {item.passenger_name}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-2 whitespace-normal break-words max-w-[350px]">
                        {item.pickup_location_label
                          ? item.pickup_location_label
                          : "N/A"}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-2 whitespace-normal break-words max-w-[350px]">
                        {item.dropoff_location_label
                          ? item.dropoff_location_label
                          : "N/A"}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-4">
                        {item.date_booked
                          ? formatDate(item.date_booked)
                          : "N/A"}
                      </TableCell>
                      <TableCell className="text-[14px] font-[400] text-[#181818] py-3 px-4">
                        {item.transfer_type || "N/A"}
                      </TableCell>
