export const LocationTag = ({
  departureTime,
  departureLabel,
  arrivalTime,
  arrivalLabel,
}: {
  departureTime?: string;
  departureLabel?: string;
  arrivalTime?: string;
  arrivalLabel?: string;
}) => {
