interface FilterProps {
  datePickerOpen: boolean;
  setDatePickerOpen: (open: boolean) => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  selectedOption: string;
  setSelectedOption: (option: string) => void;
  selectedStartDate?: string;
  setSelectedStartDate: (date: string | undefined) => void;
  selectedEndDate?: string;
  setSelectedEndDate: (date: string | undefined) => void;
  selectedDate?: string;
  setSelectedDate: (date: string | undefined) => void;
}

export const Filter: React.FC<FilterProps> = ({
  datePickerOpen,
  setDatePickerOpen,
  searchTerm,
  setSearchTerm,
  selectedOption,
  setSelectedOption,
  selectedStartDate,
  setSelectedStartDate,
  selectedEndDate,
  setSelectedEndDate,
  selectedDate,
  setSelectedDate,
}) => {
  const [inputValue, setInputValue] = useState("");

  // Sync inputValue with searchTerm
  useEffect(() => {
    setInputValue(searchTerm);
  }, [searchTerm]);

  // Handle search input
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setInputValue(val);

    // Debounce search or trigger immediately if empty
    if (val === "") {
      setSearchTerm("");
    }
  };

  const handleSearchEnter = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      setSearchTerm(inputValue);
    }
  };

  // Format date display
  const formatDateDisplay = () => {
    if (selectedStartDate && selectedEndDate) {
      return `${selectedStartDate} - ${selectedEndDate}`;
    } else if (selectedStartDate || selectedEndDate) {
      return selectedStartDate || selectedEndDate;
    }
    return "yyyy-mm-dd - yyyy-mm-dd";
  };

  // Filter options based on booking type context
  const getFilterOptions = () => {
    return [
      {
        id: 1,
        label: "PAID",
        value: "PAID",
      },
      {
        id: 6,
        label: "Cancelled",
        value: "cancelled",
      },
      {
        id: 2,
        label: "PENDING REFUND",
        value: "PENDING REFUND",
      },
      {
        id: 3,
        label: "REFUNDED",
        value: "REFUNDED",
      },
    ];
  };

  return (
    <div className="w-full px-4 lg:px-0">
      <div className="flex justify-between items-center gap-4 flex-col lg:flex-row w-full lg:space-x-12">
        {/* Search Input */}
        <div className="flex items-center flex-grow min-w-[220px] max-w-full border border-[#ACAEB3] rounded-full py-2 px-4 w-full">
          <img
            src="/assets/icons/search.svg"
            alt="Search Icon"
            className="w-4 h-4 flex-shrink-0"
          />

          <input
            type="text"
            className="flex-grow ml-2 text-[16px] placeholder:text-[#9B9EA4] text-[#181818] placeholder:font-light focus:outline-none placeholder:text-[16px] font-[400] min-w-0"
            placeholder="Search by Name, Reference, Location"
            value={inputValue}
            onChange={handleSearchChange}
            onKeyDown={handleSearchEnter}
            onBlur={() => setSearchTerm(inputValue)}
          />
        </div>

        <div className="flex space-x-4 w-full items-center">
          {/* Filter Dropdown */}
          <div className="mr-4">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <div className="flex items-center bg-white border border-[#EBECED] rounded-full py-3 px-5 cursor-pointer shadow-sm lg:shadow-none">
                  <span className="ml-2 text-[14px] font-light text-[#181818]">
                    {selectedOption || "Filter by Status"}
                  </span>
                  <img
                    src="/assets/icons/chevron-down.svg"
                    alt="Chevron"
                    className="w-4 h-4 ml-2 flex-shrink-0 rotate-90"
                  />
                </div>
              </DropdownMenuTrigger>

              <DropdownMenuContent className="w-48 mt-1 border border-gray-300 rounded-lg bg-white shadow-lg">
                <DropdownMenuItem
                  className="px-3 py-2 font-[400] text-[12px] text-[#181818] cursor-pointer"
                  onClick={() => setSelectedOption("")}
                >
                  All
                </DropdownMenuItem>
                {getFilterOptions().map((option) => (
                  <DropdownMenuItem
                    key={option.id}
                    className="px-3 py-2 font-[400] text-[12px] text-[#181818] cursor-pointer capitalize"
                    onClick={() => setSelectedOption(option.value)}
                  >
                    {option.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          {/* Date Picker */}
          <div className="flex space-x-3">
            <div className="flex items-center w-full gap-3">
              <div
                className="flex items-center bg-white border border-[#EBECED] rounded-full py-3 px-5 cursor-pointer flex-shrink-0 shadow-sm lg:shadow-none"
                onClick={() => setDatePickerOpen(true)}
              >
                <img
                  src="/assets/icons/calendar.svg"
                  alt="Calendar Icon"
                  className="w-6 flex-shrink-0"
                />
                <div className="ml-2 flex flex-col lg:flex-row lg:items-center">
                  <span className="text-[14px] font-light text-[#181818]">
                    Select Date
                  </span>
                  <span className="text-[14px] font-light text-[#9B9EA4] hidden xl:inline-block lg:ml-1 truncate">
                    {formatDateDisplay()}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Date Picker Dialog */}
      <DatePairDialog
        isOpen={datePickerOpen}
        onClose={() => setDatePickerOpen(false)}
        selectedStartDate={selectedStartDate}
        setSelectedStartDate={setSelectedStartDate}
        selectedEndDate={selectedEndDate}
        setSelectedEndDate={setSelectedEndDate}
      />
    </div>
  );
};

"use client";
import React, { useState } from "react";
import { useMyRoles } from "@/hooks/api/roles";
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useEditServices } from "@/hooks/api/cms";
import { Formik, Form, Field } from "formik";
import { AlertTriangle } from "lucide-react";
import * as Yup from "yup";


const EditDialog = ({ serviceId, refresh, canEdit }: any) => {
  const { onCMSdata, loading } = useEditServices();
  const [showSuccessModal, setShowSuccessModal] = useState(false); // Separate state for success modal

  const handleSubmit = async (values: { percentage: string }) => {
    try {
      await onCMSdata({
        id: serviceId,
        payload: values,
      });

      setShowSuccessModal(true); // Show success modal
      // Trigger refresh in the background
      refresh?.();
    } catch (error) {
      console.error("Error updating data:", error);
    }
  };

  const validationSchema = Yup.object({
    percentage: Yup.number()
      .required("Commission rate is required")
      .min(0, "Percentage must be at least 0")
      .max(100, "Percentage must be at most 100"),
  });

  return (
    <>
      <Dialog>
        <DialogTrigger asChild>
          <button className="rounded-md text-[#023E8A] font-semibold text-xs lg:text-sm cursor-pointer">
            Edit
          </button>
        </DialogTrigger>
        <DialogContent className="p-0 min-w-[335px] lg:min-w-[800px]">
          <div className="py-6 space-y-4">
            <DialogHeader className="border-b-[1px] border-[#9B9EA4]">
              <DialogTitle className="px-6 pb-6">Stays Commission Rate</DialogTitle>
            </DialogHeader>
            {!canEdit ? (
              <NotAuthorizedModal />
            ) : (
              <div className="px-6 space-y-8">
                <Formik
                  initialValues={{ percentage: "" }}
                  validationSchema={validationSchema}
                  onSubmit={handleSubmit}
                >
                  {({ isValid, values }) => (
                    <Form>
                      <div className="space-y-3">
                        <label className="block text-[14px] lg:text-[20px] font-[500] text-[#181818]">
                          Commission Rate
                        </label>
                        <div className="flex py-4 px-3 border-[#818489] border-[1px] rounded-[8px] space-x-2 items-center">
                          <img src="/assets/icons/percentage.svg" alt="" />
                          <Field
                            name="percentage"
                            type="text"
                            className="outline-none flex-1"
                            placeholder="Enter commission rate"
                          />
                        </div>
                        <div className="flex bg-[#F5F5F5] p-4 rounded-[12px] space-x-[10px] items-start">
                          <img src="/assets/icons/in-fo.svg" alt="" />
                          <p>
                            The commission rate is the percentage added on top of the base price
