"use client";
import React from "react";
import { useRef, useEffect, useState, useMemo } from "react";
import { useFormik } from "formik";
import * as Yup from "yup";
import { useRouter } from "next/navigation";
import { useGetChat } from "@/hooks/api/chat";
import { useParams } from "next/navigation";
import { format } from "date-fns";
import { useWebSocketService } from "@/hooks/api/chat";
import ChatService from "@/services/chat";
import { useAuthContext } from "@/context/AuthContext";
import { useMyRoles } from "@/hooks/api/roles";
import { FileText, ArrowUpRight, DownloadIcon, X } from "lucide-react";
import { getCookies } from "@/context/Auth-Cookies";
const Spinner = () => (
  <svg
    className="inline w-6 h-6 ml-2 animate-spin text-white"
    viewBox="0 0 24 24"
  >
    <circle
      className="opacity-25"
      cx="12"
      cy="12"
      r="10"
      stroke="currentColor"
      strokeWidth="6"
      fill="none"
    />
    <path
      className="opacity-75"
      fill="currentColor"
      d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"
    />
  </svg>
);

const formatDate = (isoDate: any) => {
  if (!isoDate) {
    return "Invalid date";
  }

  const date = new Date(isoDate);

  if (isNaN(date.getTime())) {
    return "Invalid date";
  }

  return format(date, "EEEE dd/MM/yyyy | hh:mm a");
};

export const MainChatComponents = ({ sessionId, accessToken }: any) => {
  const APP_STATE = useAuthContext();
  const currentUser = APP_STATE?.user?.user_id || "";
  const authAccessToken = APP_STATE?.accessToken || accessToken;
  const { id } = useParams<{ id: string }>();

  const { chat, loadingChat } = useGetChat({
    ChatId: sessionId as string,
    initialFetch: !!id,
    successCallback: (message) => {
      console.log(message);
    },
    errorCallback: (error) => {
      console.error(error);
    },
  });
  const { loading, data } = useMyRoles({ modalVisible: chat?.id });
  const canViewMessage =
    data?.current_permission_group_slugs?.includes("support-tickets") ||
    data?.current_permission_group_slugs?.includes("customer-support") ||
    data?.name === "Super Admin";

  const isInputDisabled = chat?.status === "CLOSED" || !canViewMessage;
  !(
    chat?.assigned_admin_info === null ||
    chat?.claimed_by_info?.id === currentUser ||
    chat?.assigned_admin_info?.id === currentUser
  );

  const router = useRouter();
  const [closing, setClosing] = useState(false);

  // Close chat handler
  const handleCloseChat = async () => {
    if (!chat?.id) return;
    setClosing(true);
    try {
      await ChatService.closeChat({ id: chat.id });
      // Optionally, show a toast or notification
      router.push("/Dashboard/support/chats"); // Redirect after closing
    } catch (error) {
      // Optionally, show error toast
      console.error(error);
    } finally {
      setClosing(false);
    }
  };
  return (
    <div className="space-y-[24px]">
      <div className="flex justify-between items-center">
        <img
          src="/assets/icons/arrow-back.svg"
          alt="Back"
          className="cursor-pointer"
          onClick={() => router.back()}
        />
        <div className="flex space-x-6">
          <button
            className={`rounded-[8px] font-medium p-4 cursor-pointer ${
              isInputDisabled
                ? "bg-gray-300 text-gray-500 cursor-not-allowed"
                : "bg-[#023E8A] text-white"
            }`}
            onClick={handleCloseChat}
            disabled={closing || isInputDisabled || !canViewMessage}
          >
            {closing ? "Closing..." : "Close chat"}
          </button>
        </div>
      </div>

      {loadingChat ? (
        <p className="">Loading</p>
      ) : (
        <div className="space-y-4">
          <p className="font-medium text-[16px] text-[#181818]">
            {formatDate(chat?.created_at)}
          </p>
          <div className="flex space-x-3 items-center">
            <p className="lg:text-[16px] text-[12px]  font-semibold text-[#4E4F52]">
              Customer:{" "}
              <span className="font-medium">
                {chat?.user_info.first_name} {chat?.user_info.last_name}
              </span>
            </p>
            <div className="w-2 h-2 bg-[#9B9EA4] rounded-full"></div>
            <p className="lg:text-[16px] text-[12px]  font-semibold text-[#4E4F52]">
              Chat ID:{" "}
              <span className="font-medium">{"Chat--" + chat?.id}</span>
            </p>
            <div className="w-2 h-2 bg-[#9B9EA4] rounded-full"></div>
            <p className="lg:text-[16px] text-[12px] font-semibold text-[#4E4F52] capitalize">
              Chat Status:{" "}
              <span className="font-medium capitalize ">{chat?.status}</span>
            </p>
          </div>
        </div>
      )}

      <Session
        chat={chat}
        loadingChat={loadingChat}
        isAdmin={isInputDisabled}
        canViewMessage={canViewMessage}
        currentUser={currentUser}
        accessToken={authAccessToken}
      />
    </div>
  );
};

export const Session = ({
  chat,
  loadingChat,
  isAdmin,
  canViewMessage,
  currentUser,
  accessToken,
}: any) => {
  const {
    messages: liveMessages,
    send,
    socket,
  } = useWebSocketService({ sessionId: chat?.id, accessToken });
  const [input, setInput] = useState("");
  const lastMessageRef = useRef<HTMLDivElement | null>(null);
  const [modalImage, setModalImage] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [uploadingMessages, setUploadingMessages] = useState<any[]>([]);

  const handleDownload = () => {
    if (!modalImage) return;
    fetch(modalImage)
      .then((response) => response.blob())
      .then((blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.style.display = "none";
        a.href = url;
        a.download = "image";
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
      })
      .catch((err) => console.error("Failed to download image:", err));
  };

  const handleCloseModal = () => setModalImage(null);
  const handleImageClick = (url: string) => setModalImage(url);

  const handleAttachmentChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        const base64String = reader.result as string;
        const clientMessageId = Date.now();
        const payload = {
          clientMessageId, // for tracking
          message: file.name, // Use file name as content
          chatId: chat?.id,
          attachment: base64String, // base64 string
          attachmentType: file.type,
        };
        setUploadingMessages((prev) => [
          ...prev,
          {
            clientMessageId,
            message: file.name,
            sender_id: currentUser,
            attachment_type: "other",
            uploading: true,
            created_at: new Date().toISOString(),
          },
        ]);
        send(payload);
      };
      reader.readAsDataURL(file);
    }
  };

  const systemErrorMessage = useMemo(() => {
    const errorMsgObj = liveMessages.find((msg: any) => msg.type === "error");
    return errorMsgObj ? errorMsgObj.message : null;
  }, [liveMessages]);

  // Remove uploading message when real message arrives (match by clientMessageId)
  useEffect(() => {
    if (uploadingMessages.length === 0) return;
    setUploadingMessages((prev) =>
      prev.filter(
        (umsg) =>
          !liveMessages.some(
            (msg: any) =>
              (msg.clientMessageId &&
                msg.clientMessageId === umsg.clientMessageId) ||
              // fallback: match by file name, sender, and created_at (if backend doesn't echo clientMessageId)
              (msg.message === umsg.message && msg.sender_id === umsg.sender_id)
          )
      )
    );
  }, [liveMessages]);

  const allMessages = useMemo(() => {
    const history = chat?.messages || [];
    const live = liveMessages.filter(
      (live: any) =>
        live.type !== "session_info" &&
        live.type !== "error" &&
        !history.some((msg: any) => msg.id === live.id)
    );
    return [...history, ...live, ...uploadingMessages];
  }, [chat?.messages, liveMessages, uploadingMessages]);

  const handleSend = () => {
    if (input.trim()) {
      const payload = {
        messageId: Date.now(),
        message: input,
        chatId: chat?.id,
      };

      send(payload);
      setInput("");
    }
  };

  useEffect(() => {
    if (lastMessageRef.current) {
      lastMessageRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [allMessages, systemErrorMessage]);

  const isInputDisabled =
    chat?.status === "CLOSED" || systemErrorMessage !== null || isAdmin;

  return (
    <>
      <div className="w-full pt-6 border border-gray-300 bg-gray-100 rounded-lg flex flex-col">
        <div className="flex justify-center items-center space-x-4 p-4">
          <div className="w-48 h-0.5 bg-black"></div>
          <div className="rounded-full border border-black py-2 px-4 text-black">
            {loadingChat ? (
              <span className="text-gray-500">Loading...</span>
            ) : (
              <div className=" text-[12px] lg:text-sm">
                {chat?.claimed_by_info?.first_name ||
                chat?.assigned_admin_info?.email ? (
                  <>
                    Responding:{" "}
                    {chat?.claimed_by_info?.first_name ||
                      chat?.claimed_by_info?.email ||
                      chat?.assigned_admin_info?.first_name ||
                      chat?.assigned_admin_info?.email ||
                      "---"}
                  </>
                ) : (
                  "No admin claimed"
                )}
              </div>
            )}
          </div>
          <div className="w-48 h-0.5 bg-black"></div>
        </div>

        {loadingChat ? (
          <div className="text-center text-gray-500">Loading messages...</div>
        ) : (
          <div className="flex-1 overflow-auto p-4 space-y-4">
            {allMessages.map((mes: any, index: any) => {
              const isUser =
                chat?.user_info?.id === mes.sender_info?.id ||
                chat?.user_info?.id === mes.sender_id;
              return (
                <div
                  key={index}
                  className={`flex ${isUser ? "justify-end" : "justify-start"}`}
                  ref={index === allMessages.length - 1 ? lastMessageRef : null}
                >
                  <div className="space-y-1 max-w-[80%]">
                    {mes.content || mes.message ? (
                      <div
                        className={`py-3 px-4 text-sm font-medium rounded-xl shadow-md ${
                          isUser
                            ? "bg-gray-200 text-black"
                            : "bg-[#023E8A] text-white"
                        }`}
                      >
                        {mes.content || mes.message}
                        {mes.uploading && <Spinner />}
                      </div>
                    ) : null}

                    {mes.attachment_url && (
                      <div className="mt-2">
                        {mes.attachment_type === "other" ? (
                          <img
                            src={mes.attachment_url}
                            alt="Attachment"
                            className={`w-[250px] h-auto rounded-lg shadow-lg cursor-pointer ${
                              isUser ? "ml-auto" : "mr-auto"
                            }`}
                            onClick={() => handleImageClick(mes.attachment_url)}
                          />
                        ) : (
                          <a
                            href={mes.attachment_url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className={`w-[250px] flex items-center justify-between gap-2 text-blue-500 h-[50px] bg-blue-100 hover:bg-blue-200 transition-all duration-300 font-semibold px-4 py-2 rounded-lg shadow-md ${
                              isUser ? "ml-auto" : "mr-auto"
                            }`}
                          >
                            <FileText className="w-5 h-5" />
                            <span>Download</span>
                            <DownloadIcon className="w-5 h-5" />
                          </a>
                        )}
                      </div>
                    )}

                    <span
                      className={`block text-xs text-gray-500 ${
                        isUser ? "text-right" : "text-left"
                      }`}
                    >
                      {mes.created_at
                        ? format(new Date(mes.created_at), "h:mm a")
                        : ""}
                    </span>
                  </div>
                </div>
              );
            })}

            {systemErrorMessage && (
              <div className="flex justify-center">
                <div className="bg-red-100 text-red-800 text-center px-4 py-2 rounded-md shadow-md max-w-[80%]">
                  {systemErrorMessage}
                </div>
              </div>
            )}
          </div>
        )}

        <div className="p-4 border-t flex items-center gap-4">
          {chat?.status === "resolved" ? (
            <p className="text-center w-full text-gray-500">
              This chat has been marked as resolved
            </p>
          ) : (
            <>
              <div className="bg-gray-200 flex-1 p-3 border rounded-lg flex items-center space-x-4">
                <div className="flex justify-between items-center w-full">
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Type a message..."
                    className="flex-1 w-full outline-none bg-transparent"
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && !isInputDisabled) {
                        handleSend();
                      }
                    }}
                    disabled={isInputDisabled}
                  />
                  <div>
                    <label htmlFor="attachment-input">
                      <img
                        src="/assets/icons/attach-ment.svg"
                        alt="Attach"
                        className="cursor-pointer"
                      />
                    </label>
                    <input
                      id="attachment-input"
                      type="file"
                      className="hidden"
                      onChange={handleAttachmentChange}
                      accept=".jpg,.jpeg,.png,.pdf,.doc,.docx"
                    />
                  </div>
                </div>
              </div>
              <button
                onClick={handleSend}
                className={`p-3 rounded-lg ${
                  isInputDisabled
                    ? "bg-gray-300 text-gray-500 cursor-not-allowed"
                    : "bg-[#023E8A] text-white"
                }`}
                disabled={isInputDisabled}
              >
                Send
              </button>
            </>
          )}
        </div>
      </div>

      {modalImage && (
        <div className="fixed inset-0 bg-black/50 bg-opacity-75 flex justify-center items-center z-50">
          <div className="relative w-auto max-w-3xl max-h-[90vh]">
            <div className="absolute top-4 right-4 flex gap-2">
              <button
                className="text-white bg-black bg-opacity-50 rounded-full p-2"
                onClick={handleCloseModal}
                aria-label="Close image preview"
              >
                <X className="w-6 h-6" />
              </button>
              <button
                onClick={handleDownload}
                className="text-white bg-black bg-opacity-50 rounded-full p-2"
                aria-label="Download image"
              >
                <DownloadIcon className="w-6 h-6" />
              </button>
            </div>
            <img
              src={modalImage}
              alt="Modal Content"
              className="max-w-full max-h-full rounded-lg shadow-lg"
            />
          </div>
        </div>
      )}
    </>
  );
};

"use client";
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableCell,
} from "@/components/ui/table";
import { useState, useEffect } from "react";
import { formatDistanceToNow, parseISO, format, addDays } from "date-fns";
import { useGetAllChat, useGetChat, useClaimChat } from "@/hooks/api/chat";
import { useRouter } from "next/navigation";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  ChatDetailsDialog,
  ChatTableDropdown,
  ClaimedChatSection,
} from "./ChatReuseables";

export const MessageTabContent: React.FC<any> = ({
  selectedOption,
  searchTerm,
  selectedEndDate,
  selectedStartDate,
  date,
}) => {
  const router = useRouter();
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [activeModal, setActiveModal] = useState<"details" | "claim" | null>(
    null
  );
  const [statusFilter, setStatusFilter] = useState<string>(
    selectedOption || ""
  );
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Add state to track previous values for comparison
  const [prevSearchTerm, setPrevSearchTerm] = useState(searchTerm);
  const [prevSelectedEndDate, setPrevSelectedEndDate] =
    useState(selectedEndDate);
  const [prevSelectedStartDate, setPrevSelectedStartDate] =
    useState(selectedStartDate);
  const [prevDate, setPrevDate] = useState(date);

  const {
    chats: fetchedChats,
    loadNext,
    loading,
    error: chatError,
    nextPageUrl,
    setFilters,
  } = useGetAllChat();

  const [chats, setChats] = useState<any[]>([]); // Maintain local chat state

  console.log({ selectedEndDate, selectedStartDate });

  const { chat: chatDetails, loadingChat } = useGetChat({
    ChatId: ticketId as string,
    initialFetch: !!ticketId,
  });

  const { claiming, onClaiming } = useClaimChat();

  // Function to trigger full reload
  const triggerFullReload = () => {
    setChats([]); // Reset chats array
    setIsInitialLoad(true); // Reset initial load flag
    setIsLoadingMore(false); // Reset loading more state
  };

  useEffect(() => {
    const filters: any = {};
    filters.status = statusFilter === "all" ? "" : statusFilter;

    if (searchTerm) {
      filters.search = searchTerm;
    }

    if (selectedStartDate) {
      filters.created_after = selectedStartDate;
    }

    if (selectedEndDate) {
      filters.created_before = selectedEndDate;
    }

    if (date) {
      filters.date = date as string;
    }

    // Check if any filter prop has changed from previous values
    if (
      searchTerm !== prevSearchTerm ||
      selectedEndDate !== prevSelectedEndDate ||
      selectedStartDate !== prevSelectedStartDate ||
      date !== prevDate
    ) {
      triggerFullReload();
      setPrevSearchTerm(searchTerm);
      setPrevSelectedEndDate(selectedEndDate);
      setPrevSelectedStartDate(selectedStartDate);
      setPrevDate(date);
    }

    setFilters(filters);
  }, [
    statusFilter,
    searchTerm,
    selectedStartDate,
    selectedEndDate,
    date,
    setFilters,
    prevSearchTerm,
    prevSelectedEndDate,
    prevSelectedStartDate,
    prevDate,
  ]);

  useEffect(() => {
    if (fetchedChats && fetchedChats.length > 0) {
      setChats(fetchedChats);
      setIsLoadingMore(false);
      setIsInitialLoad(false);
    }
  }, [fetchedChats]);

  const handleViewDetails = (chat: any) => {
    setSelectedTicket(chat);
    setTicketId(chat.id);
    setActiveModal("details");
  };

  const handleOpenClaimModal = (chat: any) => {
    setSelectedTicket(chat);
    setTicketId(chat.id);
    setActiveModal("claim");
  };

  const closeModal = () => {
    setActiveModal(null);
    setSelectedTicket(null);
    setTicketId(null);
  };

  const handleTabChange = (value: string) => {
    setStatusFilter(value === "all" ? "" : value);

    // Trigger full reload when filter changes
    triggerFullReload();

    // Set filters to trigger data refetch
    const filters: any = {};
    filters.status = value === "all" ? "" : value;

    if (searchTerm) {
      filters.search = searchTerm;
    }

    if (selectedStartDate) {
      filters.created_after = selectedStartDate;
    }

    if (selectedEndDate) {
      filters.created_before = selectedEndDate;
    }

    if (date) {
      filters.date = date as string;
    }

    setFilters(filters);
  };

  const handleLoadMore = () => {
    setIsLoadingMore(true);
    loadNext();
  };

  const styling =
    "px-[24px] h-full data-[state=active]:text-black data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:rounded-none data-[state=active]:border-b-[2px] data-[state=active]:border-b-[#181818] flex items-center justify-center cursor-pointer bg-transparent shadow-none rounded-none";

  return (
    <>
      <div className="space-y-[32px]">
        <div className="flex justify-between items-center mb-4 px-[16px]">
          <h2 className="lg:text-[20px] text-[14px] text-[#181818] font-[500] lg:font-[600]">
            Chats
          </h2>
        </div>

        <Tabs
          defaultValue="all"
          className="space-y-[40px]"
          onValueChange={handleTabChange}
        >
          <TabsList className="w-full flex justify-center items-center border-b-[1px] border-[#ACAEB3] bg-transparent shadow-none rounded-none pb-0">
            <TabsTrigger value="all" className={styling}>
              All
            </TabsTrigger>
            <TabsTrigger value="WAITING" className={styling}>
              Waiting
            </TabsTrigger>
            <TabsTrigger value="ACTIVE" className={styling}>
              Active
            </TabsTrigger>
            <TabsTrigger value="CLOSED" className={styling}>
              Closed
            </TabsTrigger>
          </TabsList>

          {loading && chats.length === 0 && isInitialLoad ? (
            <div className="h-[200px] flex justify-center items-center">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
            </div>
          ) : chats.length === 0 && !loading ? (
            <div className="h-[40px] flex justify-center items-center">
              <p className="text-[20px] font-[500] text-[#181818]">
                No data found
              </p>
            </div>
          ) : (
            <div className="lg:px-[24px] px-[4px]">
              <div className="overflow-x-auto">
                <Table className="border-none border-collapse min-w-[600px]">
                  <TableHeader>
                    <TableRow className="items-center border-none hover:bg-none">
                      <TableCell className="font-semibold border-none min-w-[200px] whitespace-nowrap">
                        Message Preview
                      </TableCell>
                      <TableCell className="font-semibold border-none min-w-[180px] whitespace-nowrap">
                        Customer
                      </TableCell>
                      <TableCell className="font-semibold border-none whitespace-nowrap">
                        Created at
                      </TableCell>
                      <TableCell className="font-semibold border-none whitespace-nowrap">
                        Status
                      </TableCell>
                      <TableCell className="font-semibold border-none whitespace-nowrap">
                        Action
                      </TableCell>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {chats.map((chat, index) => (
                      <TableRow
                        key={`${chat.id}-${index}`}
                        className="items-center cursor-pointer border-none"
                      >
                        <TableCell className="border-none min-w-[200px] whitespace-nowrap">
                          <div className="flex items-center space-x-4">
                            <div className="space-y-[8px]">
                              <h2 className="font-medium text-[#181818] text-[14px] lg:text-[16px]">
                                {chat.title}
                              </h2>
                              <p className="text-[#9B9EA4] text-[12px]">
                                {"Chat--00" + chat.id}
                              </p>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell className="border-none min-w-[180px] whitespace-nowrap">
                          <div className="space-y-2">
                            <p className="text-[#181818] text-[14px] font-[500] capitalize">
                              {chat.user_info.first_name || "---"}{" "}
                              {chat.user_info.last_name || "---"}
                            </p>
                            <p className="text-[#9B9EA4] text-[12px]">
                              {chat.user_info.email || "---"}
                            </p>
                          </div>
                        </TableCell>
                        <TableCell className="table-cell border-none whitespace-nowrap">
                          <div className="space-y-2">
                            <p className="text-[#181818] text-[14px] font-[500]">
                              {format(parseISO(chat.created_at), "dd/MM/yyyy")}
                            </p>
                            <p className="text-[#9B9EA4] text-[12px]">
                              <span>{getRelativeTime(chat.created_at)}</span>
                            </p>
                          </div>
                        </TableCell>
                        <TableCell className="border-none whitespace-nowrap">
                          <span
                            className={`px-4 py-3 rounded-md text-[10px] lg:text-[12px] ${
                              chat.status === "WAITING"
                                ? "bg-[#CCD8E8] text-[#181818]"
                                : chat.status === "ACTIVE"
                                ? "bg-[#EFB60880]/50  text-[#181818]"
                                : chat.status === "resolved"
                                ? "bg-[#2D9C5E80]/50  text-[#181818]"
                                : "bg-gray-100 text-gray-600"
                            }`}
                          >
                            {chat.status.replace("_", " ").toUpperCase()}
                          </span>
                        </TableCell>
                        <TableCell className="border-none whitespace-nowrap">
                          <ChatTableDropdown
                            parentWidth={180}
                            onViewDetails={() => handleOpenClaimModal(chat)}
                            onViewMessage={() => handleViewDetails(chat)}
                          />
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          )}

          {nextPageUrl && (
            <div className="flex justify-center mt-4">
              <button
                className="bg-[#EBECED] cursor-pointer rounded-[8px] px-[40px] py-[16px] flex items-center"
                onClick={handleLoadMore}
                disabled={isLoadingMore}
              >
                {isLoadingMore ? (
                  <div className="w-5 h-5 border-2 border-[#023E8A] border-t-transparent rounded-full animate-spin"></div>
                ) : (
                  <p className="text-[#023E8A] text-[14px]">Load more</p>
                )}
              </button>
            </div>
          )}
        </Tabs>
      </div>

      {activeModal === "details" && (
        <ChatDetailsDialog
          selectedTicket={selectedTicket}
          chatDetails={chatDetails}
          chatLoading={loadingChat}
          onClose={closeModal}
        />
      )}

      {activeModal === "claim" && (
        <ClaimedChatSection
          selectedTicket={selectedTicket}
          chatDetails={chatDetails}
          chatLoading={loadingChat}
          onClose={closeModal}
        />
      )}
    </>
  );
};

export function getRelativeTime(timestamp: string): string {
  const date = parseISO(timestamp);
  return formatDistanceToNow(date, { addSuffix: true });
}

const Skeleton = ({ rows = 5, columns = 4 }) => {
  return (
    <div className="w-full space-y-[12px] mt-5 px-4 ">
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <div
          key={rowIndex}
          className="flex justify-between items-center w-full"
        >
          {Array.from({ length: columns }).map((_, colIndex) => (
            <div
              key={colIndex}
              className="bg-gray-300 animate-pulse h-[50px] w-[24%] rounded-[12px]"
            ></div>
          ))}
        </div>
      ))}
    </div>
  );
};

"use client";
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableCell,
} from "@/components/ui/table";
import { useState, useEffect } from "react";
import { formatDistanceToNow, parseISO, format, addDays } from "date-fns";
import {
  TableDropdown,
  TicketDetailsDialog,
  ViewingChatModal,
} from "./Reuseables";
import { useGetAllEscalatedTickets, useGetTicket } from "@/hooks/api/ticket";
import { useRouter } from "next/navigation";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  EscalatedTicketChatModal,
  EscalatedTicketDetailsDialog,
} from "./Reuseables";

export const EscaleteTable: React.FC = ({ searchTerm, date }: any) => {
  const router = useRouter();
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [isDetailsDialogOpen, setIsDetailsDialogOpen] = useState(false);
  const [isChatModalOpen, setIsChatModalOpen] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>("");

  const { tickets, loading, error, setFilters } = useGetAllEscalatedTickets();

  const { ticket: ticketDetails, loadingTicket } = useGetTicket({
    TicketId: ticketId as string,
    initalFetch: !!ticketId,
    successCallback: (message) => {
      console.log(message);
    },
    errorCallback: (error) => {
      console.error(error);
    },
  });

  const handleViewDetails = (ticket: any) => {
    setIsDetailsDialogOpen(true);
    setIsChatModalOpen(false); // Ensure chat modal is closed
    setSelectedTicket(ticket);
    setTicketId(ticket.id);
  };

  const handleViewMessage = (ticket: any) => {
    setIsChatModalOpen(true);
    setIsDetailsDialogOpen(false); // Ensure details dialog is closed
    setSelectedTicket(ticket);
    setTicketId(ticket.id);
  };

  const handleDetailsDialogClose = () => {
    setIsDetailsDialogOpen(false);
    setSelectedTicket(null);
    setTicketId(null);
  };

  const handleChatModalClose = () => {
    setIsChatModalOpen(false);
    setSelectedTicket(null);
    setTicketId(null);
  };

  useEffect(() => {
    const filters: any = {};
    filters.status = statusFilter === "all" ? "" : statusFilter;
    if (searchTerm) {
      filters.search = searchTerm;
    }
    if (date) {
      filters.date = date as string;
    }
    setFilters(filters);
  }, [statusFilter, searchTerm, date, setFilters]);

  const handleTabChange = (value: string) => {
    setStatusFilter(value);
    setFilters({ status: value === "all" ? "" : value });
  };

  const lastEscalationRoleName = tickets?.length
    ? tickets[tickets.length - 1]?.escalation_role?.name || "No Role Found"
    : "No Tickets Available";

  const styling =
    "px-[24px] h-full  data-[state=active]:text-black data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:rounded-none data-[state=active]:border-b-[2px] data-[state=active]:border-b-[#181818] flex items-center justify-center cursor-pointer bg-transparent shadow-none rounded-none";

  return (
    <>
      <div className="space-y-[32px]">
        <div className="flex justify-between items-center mb-4 px-[16px]">
          <h2 className="lg:text-[20px] text-[14px] text-[#181818] font-[500] lg:font-[600]">
            Tickets
          </h2>
        </div>

        <Tabs
          defaultValue="all"
          className="space-y-[40px]"
          onValueChange={handleTabChange}
        >
          <TabsList className="w-full flex justify-center items-center border-b-[1px] border-[#ACAEB3] bg-transparent shadow-none rounded-none pb-0">
            <TabsTrigger value="all" className={styling}>
              All
            </TabsTrigger>
            <TabsTrigger value="new" className={styling}>
              New
            </TabsTrigger>
            <TabsTrigger value="in_progress" className={styling}>
              In Progress
            </TabsTrigger>
            <TabsTrigger value="resolved" className={styling}>
              Resolved
            </TabsTrigger>
          </TabsList>
          {loading ? (
            <Skeleton />
          ) : (
            <>
              {tickets.length === 0 ? (
                <div className="h-[40px] flex justify-center items-center">
                  <p className="ttext-[20px] font-[500] text-[#181818]">
                    No data found
                  </p>
                </div>
              ) : (
                <div className="lg:px-[24px] px-[16px]">
                  <Table className="border-none border-collapse">
                    <TableHeader>
                      <TableRow className="items-center border-none hover:bg-none">
                        <TableCell className="font-semibold border-none">
                          Subject
                        </TableCell>
                        <TableCell className="font-semibold border-none">
                          Customer
                        </TableCell>
                        <TableCell className="font-semibold border-none">
                          Escalated By
                        </TableCell>
                        <TableCell className="font-semibold border-none">
                          Assigned to
                        </TableCell>
                        <TableCell className="font-semibold border-none">
                          Status
                        </TableCell>
                        <TableCell className="font-semibold border-none">
                          Action
                        </TableCell>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {tickets.map((ticket: any, index: any) => (
                        <TableRow
                          key={`${ticket.id}-${index}`}
                          className="items-center cursor-pointer border-none"
                        >
                          <TableCell className="border-none">
                            <div className="flex items-center space-x-4">
                              <img
                                src="/assets/icons/flight_cancellation.svg"
                                alt="icon"
                                className="w-[30px] lg:w-[40px]"
                              />
                              <div className="space-y-[8px]">
                                <h2 className="font-medium text-[#181818] text-[14px] lg:text-[16px]">
                                  {ticket.title}
                                </h2>
                                <p className="text-[#9B9EA4] text-[12px]">
                                  {ticket.ticket_id} • {ticket.category}
                                </p>
                              </div>
                            </div>
                          </TableCell>
                          <TableCell className=" border-none">
                            <div className="space-y-2">
                              <p className="text-[#181818] text-[14px] font-[500] capitalize">
                                {ticket.user.first_name || "---"}{" "}
                                {ticket.user.last_name || "---"}
                              </p>
                              <p className="text-[#9B9EA4] text-[12px]">
                                {ticket.user.email || "---"}
                              </p>
                            </div>
                          </TableCell>
                          <TableCell className=" border-none">
                            <div className="space-y-2">
                              <p className="text-[#181818] text-[14px] font-[500]">
                                {ticket?.escalated_by?.first_name ||
                                  ticket?.escalated_by?.email}
                              </p>
                              <p className="text-[#9B9EA4] text-[12px] space-x-[2px] items-center flex">
                                {ticket?.escalated_at ? (
                                  <>
                                    <span>
                                      {format(
                                        new Date(ticket.escalated_at),
                                        "dd/MM/yyyy"
                                      )}
                                    </span>
                                    <span className="w-1 h-1 bg-[#9B9EA4] rounded-full mx-1"></span>
                                    <span>
                                      {format(
                                        new Date(ticket.escalated_at),
                                        "hh:mmaaa"
                                      )}
                                    </span>
                                  </>
                                ) : (
                                  "N/A"
                                )}
                              </p>
                            </div>
                          </TableCell>

                          <TableCell className=" border-none">
                            <div className="space-y-2">
                              <p className="text-[#181818] text-[14px] font-[500]">
                                {ticket.escalation_role?.name || "N/A"}
                              </p>
                            </div>
                          </TableCell>
                          <TableCell className="border-none whitespace-nowrap">
                            <span
                              className={`px-4 py-3 rounded-md text-[10px] lg:text-[12px] ${
                                ticket.status === "new"
                                  ? "bg-[#CCD8E8] text-[#181818]"
                                  : ticket.status === "in_progress"
                                  ? "bg-[#EFB60880]/50  text-[#181818]"
                                  : ticket.status === "resolved"
                                  ? "bg-[#2D9C5E80]/50  text-[#181818]"
                                  : "bg-gray-100 text-gray-600" // fallback for other/unknown statuses
                              }`}
                            >
                              {ticket.status.replace("_", " ").toUpperCase()}
                            </span>
                          </TableCell>
                          <TableCell className="border-none">
                            <TableDropdown
                              parentWidth={150}
                              onViewDetails={() => handleViewDetails(ticket)}
                              onViewMessage={() => handleViewMessage(ticket)}
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </>
          )}
        </Tabs>
      </div>
      <EscalatedTicketDetailsDialog
        selectedTicket={isDetailsDialogOpen}
        onClose={handleDetailsDialogClose}
        ticketDetails={selectedTicket}
        ticketLoading={loadingTicket}
      />

      <EscalatedTicketChatModal
        selectedTicket={isChatModalOpen}
        onClose={handleChatModalClose}
        ticketDetails={selectedTicket}
        ticketLoading={loadingTicket}
      />
    </>
  );
};

export function getRelativeTime(timestamp: string): string {
  const date = parseISO(timestamp);
  return formatDistanceToNow(date, { addSuffix: true });
}

const Skeleton = ({ rows = 5, columns = 4 }) => {
  return (
    <div className="w-full space-y-[12px] mt-5 px-4 ">
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <div
          key={rowIndex}
