"use client";

import { useState, useEffect } from "react";
import {
  UserDetailsDialog,
  UserDropdown,
  UserDeleteDialog,
  LoadingUser,
  NotAuthorizedModal,
} from "@/components/molecues/user/DeleteUserComponent";

import {
  useGetDeletedUsers,
  useGetUser,
  useBulkDeleteUser,
} from "@/hooks/api/user";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { format } from "date-fns";
import { useMyRoles } from "@/hooks/api/roles";
import { Dialog, DialogTrigger, DialogContent } from "@/components/ui/dialog";

const BulkDeleteConfirmationDialog = ({
  isOpen,
  selectedCount,
  onConfirm,
  onCancel,
  deleting,
}: {
  isOpen: boolean;
  selectedCount: number;
  onConfirm: () => void;
  onCancel: () => void;
  deleting: boolean;
}) => {
  const { loading, data } = useMyRoles({ modalVisible: isOpen });
  const canViewMessage = data?.name === "Super Admin";

  return (
    <Dialog open={isOpen} onOpenChange={onCancel}>
      <DialogContent className="lg:min-w-[800px] rounded-[16px] p-0 space-y-0">
        {canViewMessage ? (
          <>
            <div className="px-[32px] py-[8px]">
              <h2 className="font-[600] text-[28px] text-[#181818]">
                Confirm Bulk Deletion
              </h2>
            </div>
            <div className="w-full border-b-[1px] border-[#9B9EA4]"></div>
            <div className="py-[19px] px-[32px] space-y-[16px]">
              <p className="font-[400] text-[#4E4F52] text-[18px]">
                Are you sure you want to delete <strong>{selectedCount}</strong>{" "}
                user{selectedCount > 1 ? "s" : ""}? You are about to permanently
                erase this user from the system. This account is currently in a
                deleted state, but this action will remove all remaining data
                permanently and cannot be undone. Are you sure you want to
                continue?
              </p>
            </div>
            <div className="w-full border-b-[1px] border-[#9B9EA4]"></div>
            <div className="flex justify-end gap-4 w-full py-[19px] px-[32px]">
              <div
                className="border-[#023E8A] border-[1px] p-3 rounded-[8px] text-[#023E8A] font-[500] text-[16px] uppercase cursor-pointer"
                onClick={onCancel}
              >
                Cancel
              </div>
              <div
                className={`bg-[#D72638] p-3 rounded-[8px] text-[#fff] font-[500] text-[16px] uppercase cursor-pointer ${
                  deleting ? "opacity-50 cursor-not-allowed" : ""
                }`}
                onClick={onConfirm}
              >
                {deleting ? "Deleting..." : "Yes, Continue"}
              </div>
            </div>
          </>
        ) : (
          <NotAuthorizedModal />
        )}
      </DialogContent>
    </Dialog>
  );
};

export const DeletedUsersTable = ({ searchTerm, selectedOption }: any) => {
  const {
    users,
    loadNext,
    loadPrevious,
    loading,
    error,
    setSearchTerm,
    setIsActive,
    nextPageUrl,
    previousPageUrl,
  } = useGetDeletedUsers();

  const [selectedUser, setSelectedUser] = useState(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [deactivatingUser, setDeactivatingUser] = useState(null);
  const [isDeactivateDialogOpen, setIsDeactivateDialogOpen] = useState(false);
  const [selectedUserIds, setSelectedUserIds] = useState<string[]>([]);

  // New state for bulk delete confirmation dialog
  const [isBulkDeleteDialogOpen, setIsBulkDeleteDialogOpen] = useState(false);

  // Bulk delete hook
  const { deleting, onBulkDeleteUser, isSuccess } = useBulkDeleteUser();

  const { data: userDetails, loading: userLoading } = useGetUser({
    UserId: userId as string,
    initialFetch: !!userId,
    successCallback: (message) => {
      console.log("User details fetched successfully:", message);
    },
    errorCallback: (error) => {
      console.error("Error fetching user details:", error);
    },
  });

  useEffect(() => {
    setSearchTerm(searchTerm || "");
    setIsActive(selectedOption || null);
  }, [searchTerm, selectedOption, setSearchTerm, setIsActive]);

  // Bulk delete handlers
  const handleBulkDeleteClick = () => {
    if (selectedUserIds.length === 0) return;
    setIsBulkDeleteDialogOpen(true);
  };

  const confirmBulkDelete = async () => {
    setIsBulkDeleteDialogOpen(false);
    if (selectedUserIds.length === 0) return;

    try {
      const userIds = selectedUserIds.map((id) => parseInt(id, 10));
      await onBulkDeleteUser({
        userIds,
        successCallback: () => {
          console.log("Users deleted successfully");
          setSelectedUserIds([]);
        },
      });
    } catch (error) {
      console.error("Error during bulk deletion:", error);
    }
  };

  const cancelBulkDelete = () => {
    setIsBulkDeleteDialogOpen(false);
  };

  const handleViewDetails = (user: any) => {
    setSelectedUser(user);
    setUserId(user.id);
  };

  const handleDeactivateUser = (user: any) => {
    setDeactivatingUser(user);
    setIsDeactivateDialogOpen(true);
  };

  const confirmDeactivation = () => {
    if (deactivatingUser) {
      setDeactivatingUser(null);
      setIsDeactivateDialogOpen(false);
    }
  };

  const handleDialogClose = () => {
    setSelectedUser(null);
    setUserId(null);
  };

  const cancelDeactivation = () => {
    setDeactivatingUser(null);
    setIsDeactivateDialogOpen(false);
  };

  const toggleSelectUser = (userId: string) => {
    setSelectedUserIds((prev) =>
      prev.includes(userId)
        ? prev.filter((id) => id !== userId)
        : [...prev, userId]
    );
  };

  const handleSelectAll = (checked: boolean) => {
    setSelectedUserIds(checked ? users.map((user) => user.id) : []);
  };

  return (
    <div className="relative w-full">
      {selectedUserIds.length > 0 && (
        <div className="flex justify-end mb-4">
          <button
            className={`text-white text-[14px] font-[400] py-2 px-4 rounded-[8px] transition duration-200 ${
              deleting
                ? "bg-gray-400 cursor-not-allowed"
                : "bg-red-500 hover:bg-red-600"
            }`}
            onClick={handleBulkDeleteClick}
            disabled={deleting}
          >
            {deleting
              ? "Deleting..."
              : `Delete Selected Users (${selectedUserIds.length})`}
          </button>
        </div>
      )}

      <div className="bg-white rounded-[20px] border border-gray-300 w-full overflow-hidden">
        <div className="max-w-[95vw] lg:max-w-full overflow-x-auto">
          <div className="inline-block min-w-full align-middle">
            {loading ? (
              <LoadingUser />
            ) : (
              <>
                {users.length === 0 ? (
                  <div className="h-[80px] flex justify-center items-center">
                    <p className="text-[20px] font-[500] text-[#181818]">
                      No data found
                    </p>
                  </div>
                ) : error ? (
                  <div className="h-[80px] flex justify-center items-center">
                    <p className="text-[20px] font-[500] text-[#181818]">
                      We cannot fetch users at the moment. Please try again.
                    </p>
                  </div>
                ) : (
                  <Table className="w-full min-w-[800px]">
                    <TableHeader className="bg-gray-100">
                      <TableRow>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left w-1/12">
                          <input
                            type="checkbox"
                            className="w-5 h-5 rounded border-gray-300 text-red-500 focus:ring-red-400"
                            onChange={(e) => handleSelectAll(e.target.checked)}
                            checked={
                              users.length > 0 &&
                              selectedUserIds.length === users.length
                            }
                            // React doesn't support indeterminate attribute on input directly,
                            // so you'd handle it via ref if needed — omitted for brevity
                          />
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          User ID
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          Name
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          Email Address
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          Registration Date
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          Deletion Date
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                          Deletion Reason
                        </TableHead>
                        <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-center">
                          Actions
                        </TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {users.map((user) => (
                        <TableRow
                          key={user.id}
                          className="bg-white hover:bg-gray-50 transition duration-200 cursor-pointer"
                        >
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            <input
                              type="checkbox"
                              className="w-5 h-5 rounded border-gray-300 text-red-500 focus:ring-red-400"
                              checked={selectedUserIds.includes(user.id)}
                              onChange={() => toggleSelectUser(user.id)}
                              disabled={deleting}
                            />
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user.id}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user.name}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user.email}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user.registration_date
                              ? format(new Date(user.registration_date), "MM/dd/yyyy")
                              : "---"}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user.deleted_at
                              ? format(new Date(user.deleted_at), "MM/dd/yyyy")
                              : "---"}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-[14px] font-[400] text-[#181818]">
                            {user?.reason || "---"}
                          </TableCell>
                          <TableCell className="py-4 px-6 text-center">
                            <UserDropdown
                              onViewDetails={() => handleViewDetails(user)}
                              onDeactivate={() => handleDeactivateUser(user)}
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </>
            )}
          </div>
        </div>
      </div>

      {selectedUser && (
        <UserDetailsDialog
          isOpen={!!selectedUser}
          selectedUser={selectedUser}
          userDetails={userDetails}
          userLoading={userLoading}
          onClose={handleDialogClose}
        />
      )}

      {isDeactivateDialogOpen && deactivatingUser && (
        <UserDeleteDialog
          isOpen={isDeactivateDialogOpen}
          deactivatingUser={deactivatingUser}
          onCancel={cancelDeactivation}
        />
      )}

      <BulkDeleteConfirmationDialog
        isOpen={isBulkDeleteDialogOpen}
        selectedCount={selectedUserIds.length}
        onConfirm={confirmBulkDelete}
        onCancel={cancelBulkDelete}
        deleting={deleting}
      />

      <div className="flex justify-end mt-[20px] space-x-4">
        <button
          className={`text-[#023E8A] text-[14px] font-[400] py-2 px-3 border-[1px] rounded-[8px] ${
            previousPageUrl && !deleting
              ? "border-[#023E8A] hover:bg-blue-50"
              : "cursor-not-allowed border-gray-300 text-gray-400"
          }`}
          disabled={!previousPageUrl || deleting}
          onClick={loadPrevious}
        >
          Previous
        </button>
        <button
          className={`text-[#023E8A] text-[14px] font-[400] py-2 px-3 border-[1px] rounded-[8px] ${
            nextPageUrl && !deleting
              ? "border-[#023E8A] hover:bg-blue-50"
              : "cursor-not-allowed border-gray-300 text-gray-400"
          }`}
          disabled={!nextPageUrl || deleting}
          onClick={loadNext}
        >
          Next
        </button>
      </div>
    </div>
  );
};

"use client";
import { useState, useEffect } from "react";
import {
  UserDetailsDialog,
  UserDeactivationDialog,
  UserDropdown,
  LoadingUser,
  UserActivationDialog,
} from "@/components/molecues/user/AllUserComponents";

import { useGetUsers, useExportCSV, useGetUser } from "@/hooks/api/user";
import Button from "@/components/reuseables/Button";
import { useRouter } from "next/navigation";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { format } from "date-fns";
export const UsersTable = ({
  searchTerm,
  selectedOption,
  selectedEndDate,
  selectedStartDate,
}: any) => {
  const router = useRouter();
  console.log({ selectedEndDate, selectedStartDate });

  const {
    users,
    loadNext,
    loadPrevious,
    loading,
    error,
    nextPageUrl,
    previousPageUrl,
    setSearchTerm,
    setIsActive,
    setDateJoinedAfter,
    setDateJoinedBefore,
    refetch,
  } = useGetUsers();

  useEffect(() => {
    setSearchTerm(searchTerm);
  }, [searchTerm, setSearchTerm]);

  useEffect(() => {
    setIsActive(selectedOption === "" ? null : selectedOption);
  }, [selectedOption, setIsActive]);

  // New effect for setting date filters
  useEffect(() => {
    // If dates are empty strings or null, pass null to clear filter
    setDateJoinedAfter(selectedStartDate || null);
    setDateJoinedBefore(selectedEndDate || null);
  }, [
    selectedStartDate,
    selectedEndDate,
    setDateJoinedAfter,
    setDateJoinedBefore,
  ]);

  const [selectedUser, setSelectedUser] = useState(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [deactivatingUser, setDeactivatingUser] = useState(null);
  const [isDeactivateDialogOpen, setIsDeactivateDialogOpen] = useState(false);
  const [reactivatingUser, setReactivatingUser] = useState(null);
  const [isReactivateDialogOpen, setIsReactivateDialogOpen] = useState(false);

  const { data: userDetails, loading: userLoading } = useGetUser({
    UserId: userId as string,
    initalFetch: !!userId,
    successCallback: (message) => {
      console.log("User details fetched successfully:", message);
    },
    errorCallback: (error) => {
      console.error("Error fetching user details:", error);
    },
  });

  const handleViewDetails = (user: any) => {
    setSelectedUser(user);
    setUserId(user.id);
  };

  const handleDeactivateUser = (user: any) => {
    setDeactivatingUser(user);
    setIsDeactivateDialogOpen(true);
  };

  const handleReactivateUser = (user: any) => {
    setReactivatingUser(user);
    setIsReactivateDialogOpen(true);
  };

  const confirmDeactivation = () => {
    if (deactivatingUser) {
      setDeactivatingUser(null);
      setIsDeactivateDialogOpen(false);
    }
  };

  const confirmReactivation = () => {
    if (reactivatingUser) {
      setReactivatingUser(null);
      setIsReactivateDialogOpen(false);
    }
  };

  const cancelDeactivation = () => {
    setDeactivatingUser(null);
    setIsDeactivateDialogOpen(false);
  };

  const cancelReactivation = () => {
    setReactivatingUser(null);
    setIsReactivateDialogOpen(false);
  };

  const handleDialogClose = () => {
    setSelectedUser(null);
    setUserId(null);
  };

  return (
    <div className="">
      <div className="bg-white rounded-[20px] border border-gray-300 w-full overflow-hidden">
        <div className="max-w-[95vw] lg:max-w-full overflow-x-auto">
          <div className="inline-block min-w-full align-middle">
            {loading ? (
              <LoadingUser />
            ) : (
              <>
                {users.length === 0 ? (
                  <div className="h-[80px] flex justify-center items-center">
                    <p className="text-[20px] font-[500] text-[#181818]">
                      No data found
                    </p>
                  </div>
                ) : (
                  <>
                    {error ? (
                      <div className="h-[80px] flex justify-center items-center">
                        <p className="text-[20px] font-[500] text-[#181818]">
                          We cannot fetch users at the moment, please try again.
                        </p>
                      </div>
                    ) : (
                      <Table className="w-full min-w-[800px]">
                        <TableHeader className="bg-gray-100">
                          <TableRow>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                              User ID
                            </TableHead>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                              Name
                            </TableHead>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                              Email Address
                            </TableHead>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                              Registration Date
                            </TableHead>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-left">
                              Status
                            </TableHead>
                            <TableHead className="py-4 px-6 text-sm font-semibold text-gray-700 text-center">
                              Actions
                            </TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {users.map((user) => (
                            <TableRow
                              key={user.id}
                              className="bg-white hover:bg-gray-50 transition duration-200 cursor-pointer"
                            >
                              <TableCell className="py-6 px-6 text-[14px] font-[400] text-[#181818]">
                                {user.id}
                              </TableCell>
                              <TableCell className="py-6 px-6 text-[14px] font-[400] text-[#181818]">
                                {`${user.first_name || "---"} ${
                                  user.last_name || "---"
                                }`}
                              </TableCell>
                              <TableCell className="py-6 px-6 text-[14px] font-[400] text-[#181818]">
                                {user.email}
                              </TableCell>
                              <TableCell className="py-6 px-6 text-[14px] font-[400] text-[#181818]">
                                {format(
                                  new Date(user.date_created),
                                  "MM/dd/yyyy"
                                )}
                              </TableCell>
                              <TableCell className="py-6 px-6 text-sm">
                                <span
                                  className={`p-[10px] border-[1px] rounded-[12px] text-[14px] font-[400] ${
                                    user.is_active
                                      ? "bg-[#2D9C5E1A] text-green-700 border-[#2D9C5E]"
                                      : "bg-[#D726380D] text-red-700 border-[#D72638]"
                                  }`}
                                >
                                  {user.is_active ? "Active" : "Deactivated"}
                                </span>
                              </TableCell>
                              <TableCell className="py-6 px-6 text-center">
                                <UserDropdown
                                  parentWidth={180}
                                  onViewDetails={() => handleViewDetails(user)}
                                  onDeactivate={() =>
                                    handleDeactivateUser(user)
                                  }
                                  onActivate={() => handleReactivateUser(user)}
                                  status={user.is_active}
                                />
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    )}
                  </>
                )}
              </>
            )}
          </div>
        </div>
      </div>
      <div className="flex w-full justify-end space-x-5 mt-[20px]">
        <div
          className={`text-[#023E8A] text-[14px] font-[400] py-2 px-3 border-[1px] border-[#023E8A] rounded-[8px] cursor-pointer ${
            previousPageUrl
              ? "border-[#023E8A]"
              : "border-[#a3a3a3] cursor-not-allowed"
          }`}
          onClick={previousPageUrl ? loadPrevious : undefined}
        >
          Previous
        </div>
        <div
          className={`text-[#023E8A] text-[14px] font-[400] py-2 px-3 border-[1px] rounded-[8px] cursor-pointer ${
            nextPageUrl
              ? "border-[#023E8A]"
              : "border-[#a3a3a3] cursor-not-allowed"
          }`}
          onClick={nextPageUrl ? loadNext : undefined}
        >
          Next
        </div>
      </div>

      <UserDetailsDialog
        selectedUser={selectedUser}
        userDetails={userDetails}
        userLoading={userLoading}
        onClose={handleDialogClose}
      />
      <UserDeactivationDialog
        deactivatingUser={deactivatingUser}
        isOpen={isDeactivateDialogOpen}
        onConfirm={confirmDeactivation}
        onCancel={cancelDeactivation}
        refetch={refetch}
      />
      <UserActivationDialog
        reactivatingUser={reactivatingUser}
        isOpen={isReactivateDialogOpen}
        onConfirm={confirmReactivation}
        onCancel={cancelReactivation}
        refetch={refetch}
      />
    </div>
  );
};

"use client";
import React, { useState } from "react";
import ContentWrapper from "@/components/reuseables/ContentWrapper";
import {
  DropdownMenu,
  DropdownMenuContent,
