export const useWebSocketService = ({ sessionId, accessToken }: any) => {
  const [messages, setMessages] = useState<any[]>([]);
  // const [accessToken, setAccessToken] = useState<string | null>(null);
  const [socketUrl, setSocketUrl] = useState<string | null>(null);
  const [socket, setSocket] = useState<WebSocket | null>(null); // WebSocket instance

  useEffect(() => {
    if (accessToken && sessionId) {
      const wsBase = toWsBase(env.api.chat);
      const url = `${wsBase}/ws/chat/${sessionId}/?token=${accessToken}`;
      setSocketUrl(url);
    }

    return () => {
      if (socket) {
        socket.close();
      }
    };
  }, [accessToken, sessionId]);

  useEffect(() => {
    if (socketUrl) {
      const ws = new WebSocket(socketUrl);

      ws.onopen = () => console.log("WebSocket connected");
      ws.onerror = (error) => console.error("WebSocket error:", error);
      ws.onclose = (event) => {
        console.error("WebSocket closed unexpectedly:", event);
        setTimeout(() => console.log("Reconnecting WebSocket..."), 3000);
      };

      ws.onmessage = (event) => {
        const data = JSON.parse(event.data);
        setMessages((prev) => {
          if (!prev.some((msg) => msg.id === data.id)) {
            return [...prev, data];
          }
          return prev;
        });
      };

      setSocket(ws);

      return () => {
        // Close the WebSocket when the component unmounts or the session changes
        ws.close();
      };
    }
  }, [socketUrl]);
  // console.log(messages);

  const send = (message: any) => {
    if (socket && socket.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify(message));
    } else {
      console.error("WebSocket is not connected.");
    }
  };

  return { messages, send, socket };
};

