export const useWebSocketService = (accessToken: string | null) => {
  const [messages, setMessages] = useState<any[]>([]);
  const [socket, setSocket] = useState<WebSocket | null>(null);

  
  useEffect(() => {
    if (!accessToken) return;

    // Attach access token as query param
    const wsBase = toWsBase(env.api.notification);
    const url = `${wsBase}/ws/notifications/?authorization=${accessToken}`;
    const ws = new WebSocket(url);

    ws.onopen = () => {
      console.log("✅ WebSocket connected");
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        setMessages((prev) => {
          // Avoid duplicates
          if (!prev.some((msg) => msg.id === data.id)) {
            return [...prev, data];
          }
          return prev;
        });
      } catch (err) {
        console.error("Invalid WS message:", err);
      }
    };

    ws.onerror = (error) => {
      console.error("❌ WebSocket error:", error);
    };

    ws.onclose = (event) => {
      console.warn("⚠️ WebSocket closed:", event.reason);
      // Reconnect after 3s
      setTimeout(() => {
        console.log("🔄 Reconnecting WebSocket...");
        setSocket(new WebSocket(url));
      }, 3000);
    };

    setSocket(ws);

    return () => {
      ws.close();
    };
  }, [accessToken]);

  const send = (message: any) => {
    if (socket && socket.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify(message));
    } else {
      console.error("WebSocket is not connected.");
    }
  };

  return { messages, send, socket };
};

